window.TADABBUR_DUKHAN = {"_meta":{"description":"تدبّر سورة الدخان (٤٤)، وسورةٌ مكّيّةٌ من الحواميم. تُسمّى الدخانَ لذكرِ الدخانِ فيها علامةً. محورُها تعظيمُ ليلةِ القدرِ وإنزالِ القرآنِ فيها، والوعيدُ بيومِ الدخانِ والبطشةِ الكبرى، وقصةُ موسى وفرعونَ وإغراقِه، والتذكيرُ بالبعثِ ويومِ الفصل، ومقابلةُ عذابِ الزقّومِ للمجرمين بنعيمِ المتّقين في الجنّات. فيها «إنا أنزلناه في ليلة مباركة»، و«يوم تأتي السماء بدخان مبين»، و«إن يوم الفصل ميقاتهم أجمعين»، و«إن شجرة الزقوم طعام الأثيم»، و«إن المتقين في مقام أمين».","honesty":"كلُّ وقفةٍ مُسنَدةٌ إلى تفسيرٍ معتمد (ابن كثير/السعدي) وموسومةٌ بدرجتها. حالُ القلبِ والعملُ اجتهاديٌّ موسوم. لا يُقدَّم شيءٌ على أنه إعجازٌ مثبت."},"n":44,"name":"الدخان","total_ayahs":59,"audio":[1,3,10,16,40,43,51,54,58,59],"passages":[{"title":"إنزالُ القرآنِ في ليلةٍ مباركة، وتقديرُ الأمور، وتوحيدُ الله، وشكُّ المشركين","range":[1,9],"theme":"القسمُ بالكتابِ المبين، وأنّ الله أنزل القرآنَ في ليلةٍ مباركةٍ يُفرَق فيها كلُّ أمرٍ حكيمٍ رحمةً منه، وأنه ربُّ السماواتِ والأرضِ لا إله إلا هو يحيي ويميت، وأنّ المشركين في شكٍّ يلعبون","verses":[{"n":1,"reflection":{"text":"«حم»: حروفٌ مقطّعةٌ افتُتِحت بها السورةُ، من المتشابهِ الذي استأثر الله بعلمه، ويُشار بها إلى إعجازِ القرآن؛ ففي هذا تعظيمُ القرآن؛ فسلّم لله فيما استأثر بعلمه، وتدبّر ما بيّنه، فالتسليمُ فيما لم تعلم من صفاتِ الراسخين.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التسليمُ لله فيما استأثر بعلمه، والتدبّرُ لما بيّن."},"action":{"text":"اعلم أنّ سورةَ الدخانِ افتُتِحت بـ«حم» من الحروفِ المقطّعةِ التي هي من المتشابهِ الذي استأثر الله بعلمِ المرادِ منه «حم»؛ وأصحُّ ما قيل فيها الإشارةُ إلى إعجازِ القرآن المؤلَّفِ من جنسِ هذه الحروف؛ فسلّم لما استأثر الله بعلمه من المتشابه؛ وتدبّر واعمل بما بيّنه لك من المحكم؛ فالراسخون في العلمِ يقولون آمنّا به كلٌّ من عند ربنا؛ فاجعل تسليمك لله فيما لم تعلم علامةَ إيمانك؛ فبالتسليمِ والعملِ تُنال الهداية."}},{"n":2,"reflection":{"text":"«والكتاب المبين»: أقسم الله بالكتابِ الواضحِ البيّن (القرآن)؛ ففي هذا تعظيمُ شأنِ القرآن؛ فعظّم القرآنَ الذي أقسم الله به ووصفه بالبيان، وتدبّر بيانه، فالقرآنُ كتابٌ مبينٌ واضح، فاعتنِ به تلاوةً وتدبّرًا وعملًا.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ القرآنِ المبينِ والاعتناءُ به."},"action":{"text":"تأمّل قسمَ الله بكتابه: والكتابِ المبينِ الواضحِ في ألفاظه ومعانيه، المُظهِرِ للحقِّ والهدى «والكتاب المبين»؛ ففي هذا تعظيمُ شأنِ القرآنِ وبيانُ وضوحه؛ فأقسم الله به تعظيمًا لشأنه؛ فعظّم القرآنَ الذي أقسم الله به؛ فهو كتابٌ مبينٌ واضحُ الدلالة، بيّنُ الأحكامِ والأخبار؛ فتدبّر بيانه، وتأمّل معانيه؛ واعتنِ به تلاوةً وتدبّرًا وعملًا وتحكيمًا؛ فمن عظّم القرآنَ وأقبل عليه اهتدى به؛ فاجعل للقرآنِ المبينِ في قلبك مكانته اللائقة؛ فبتعظيمِ القرآنِ والعملِ به تُنال الهدايةُ والسعادة."}},{"n":3,"reflection":{"text":"«إنا أنزلناه في ليلة مباركة إنا كنا منذرين»: إنا أنزلنا القرآنَ في ليلةٍ مباركةٍ (ليلةِ القدر)، إنا كنا منذِرين للعباد؛ ففي هذا بيانُ فضلِ ليلةِ القدرِ وإنزالِ القرآنِ فيها؛ فعظّم ليلةَ القدرِ التي أُنزِل فيها القرآن، واجتهد في طلبها بالعبادة، فليلةُ القدرِ خيرٌ من ألفِ شهر، فاغتنمها بالطاعة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ ليلةِ القدرِ والاجتهادُ في طلبِها بالعبادة."},"action":{"text":"تأمّل فضلَ ليلةِ القدر: إنا أنزلنا القرآنَ في ليلةٍ مباركةٍ كثيرةِ الخيرِ والبركة، وهي ليلةُ القدرِ في رمضان؛ إنا كنا منذِرين للعبادِ بإرسالِ الرسلِ وإنزالِ الكتب رحمةً بهم «إنا أنزلناه في ليلة مباركة إنا كنا منذرين»؛ ففي هذا بيانُ فضلِ ليلةِ القدرِ وبركتِها، وأنّ القرآنَ أُنزِل فيها؛ فليلةُ القدرِ ليلةٌ مباركةٌ عظيمةٌ، أنزل الله فيها القرآنَ جملةً إلى السماءِ الدنيا؛ إنا أنزلناه في ليلةِ القدر، وما أدراك ما ليلةُ القدر، ليلةُ القدرِ خيرٌ من ألفِ شهر؛ فعظّم ليلةَ القدرِ التي أُنزِل فيها القرآن؛ واجتهد في طلبها في العشرِ الأواخرِ من رمضان بالعبادةِ والقيامِ والدعاء؛ تحرّوا ليلةَ القدرِ في الوترِ من العشرِ الأواخر؛ فمن قام ليلةَ القدرِ إيمانًا واحتسابًا غُفِر له ما تقدّم من ذنبه؛ فاغتنم ليلةَ القدرِ بالطاعةِ والقيامِ والدعاء؛ فهي خيرٌ من ألفِ شهر؛ فمن أدركها فقام فيها فقد فاز بخيرٍ عظيم؛ فاجتهد في طلبها، واغتنمها بالعبادة."}},{"n":4,"reflection":{"text":"«فيها يفرق كل أمر حكيم»: في ليلةِ القدرِ يُفصَّل ويُقدَّر كلُّ أمرٍ محكمٍ من أمورِ العباد (أرزاقهم وآجالهم)؛ ففي هذا بيانُ تقديرِ الأمورِ في ليلةِ القدر؛ فاعلم أنّ الله يقدّر الأمورَ بحكمته، فسلّم لتقديرِ الله وارضَ به، فما قُدّر في ليلةِ القدرِ نافذٌ بحكمةِ الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التسليمُ لتقديرِ الله ورضاه به، فما قدّره بحكمته نافذ."},"action":{"text":"تأمّل ما يقع في ليلةِ القدر: في تلك الليلةِ المباركةِ يُفرَق ويُفصَّل ويُكتَب من اللوحِ المحفوظِ كلُّ أمرٍ حكيمٍ محكمٍ من أمورِ تلك السنة: من الأرزاقِ والآجالِ والأقدارِ وما يكون فيها «فيها يفرق كل أمر حكيم»؛ ففي هذا بيانُ أنّ الله يقدّر ويفصّل الأمورَ في ليلةِ القدرِ بحكمته؛ فتُكتَب فيها مقاديرُ السنةِ من الأرزاقِ والآجالِ والأحداث؛ فاعلم أنّ الله يقدّر الأمورَ كلَّها بحكمته وعلمه؛ فكلُّ ما يقع في الكونِ مقدّرٌ عند الله بحكمة؛ فسلّم لتقديرِ الله وقضائه؛ وارضَ بما يقدّره لك؛ فما قُدّر في ليلةِ القدرِ وفي اللوحِ المحفوظِ نافذٌ بحكمةِ الله وعلمه؛ فما أصابك لم يكن ليخطئك، وما أخطأك لم يكن ليصيبك؛ فآمن بالقدرِ خيرِه وشرّه؛ وسلّم لله في أقداره؛ فمن سلّم لتقديرِ الله وجد الراحةَ والطمأنينة؛ ومن اعترض على قدرِ الله شقي وتعب؛ فاجعل تسليمك لله في أقداره؛ فهو الحكيمُ الذي يقدّر بحكمته ما هو خيرٌ لك."}},{"n":5,"reflection":{"text":"«أمرا من عندنا إنا كنا مرسلين»: أمرًا صادرًا من عندنا، إنا كنا مرسلين للرسل؛ ففي هذا بيانُ أنّ الأمرَ والتقديرَ من الله، وأنّ إرسالَ الرسلِ سنّتُه؛ فاعلم أنّ الأمرَ كلَّه من الله وأنّ إرسالَ الرسلِ رحمةٌ منه، فاشكر نعمةَ الرسلِ والوحي، وسلّم لأمرِ الله وتدبيره.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التسليمُ لأمرِ الله وتدبيره، وشكرُ نعمةِ إرسالِ الرسل."},"action":{"text":"تأمّل بيانَ أنّ الأمرَ من الله: أمرًا صادرًا من عندنا بحكمتنا وتدبيرنا؛ إنا كنا مرسلين للرسلِ إلى العبادِ رحمةً بهم وإقامةً للحجّة «أمرا من عندنا إنا كنا مرسلين»؛ ففي هذا بيانُ أنّ الأمرَ والتقديرَ كلَّه من عند الله، وأنّ إرسالَ الرسلِ سنّةٌ من سننه ورحمةٌ منه؛ فكلُّ ما يقع في الكونِ من أمرٍ وتقديرٍ فهو من عند الله بحكمته؛ فاعلم أنّ الأمرَ كلَّه لله، يدبّره بحكمته وعلمه؛ وأنّ إرسالَ الرسلِ رحمةٌ من الله بعباده؛ فما أرسل الله الرسلَ إلا رحمةً بالعبادِ وهدايةً لهم؛ وما أرسلناك إلا رحمةً للعالمين؛ فاشكر نعمةَ الله بإرسالِ الرسلِ وإنزالِ الوحي؛ فبهم عرف الناسُ ربهم ودينهم؛ وسلّم لأمرِ الله وتدبيره في خلقه؛ فالأمرُ كلُّه بيده يدبّره بحكمته؛ فمن سلّم لأمرِ الله وشكر نعمةَ رسله فقد أدّى حقّه؛ فاجعل تسليمك لأمرِ الله، وشكرك لنعمةِ الرسلِ والوحي."}},{"n":6,"reflection":{"text":"«رحمة من ربك إنه هو السميع العليم»: إنزالُ القرآنِ وإرسالُ الرسلِ رحمةٌ من ربّك، إنه هو السميعُ العليم؛ ففي هذا بيانُ أنّ الوحيَ والرسالةَ رحمةٌ من الله؛ فاعلم أنّ القرآنَ والرسالةَ رحمةٌ عظيمةٌ من الله، فاشكرها بالإيمانِ والعمل، والله سميعٌ لدعائك عليمٌ بحالك، فاطلب رحمته.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ رحمةِ الله بالوحيِ والرسالة، وطلبُ رحمته."},"action":{"text":"تأمّل بيانَ أنّ الوحيَ رحمة: كان إنزالُ القرآنِ وإرسالُ الرسلِ رحمةً من ربّك بعباده؛ إنه هو السميعُ لأقوالِ عباده ودعائهم، العليمُ بأحوالهم وحاجاتهم «رحمة من ربك إنه هو السميع العليم»؛ ففي هذا بيانُ أنّ إنزالَ القرآنِ وإرسالَ الرسلِ رحمةٌ عظيمةٌ من الله؛ فالقرآنُ والرسالةُ من أعظمِ رحماتِ الله بعباده؛ فبهما هداهم من الضلالة، وبصّرهم من العمى، وأنقذهم من الجهالة؛ فاعلم أنّ القرآنَ والرسالةَ رحمةٌ عظيمةٌ من الله؛ فاشكر هذه الرحمةَ بالإيمانِ بالقرآنِ والعملِ به، واتّباعِ الرسول؛ واعلم أنّ الله هو السميعُ لدعائك وأقوالك، العليمُ بحالك وحاجاتك؛ فراقبه في سرّك وعلنك؛ واطلب رحمته بالإيمانِ والطاعةِ والدعاء؛ فمن شكر رحمةَ الله بالوحيِ والرسالةِ زاده الله من رحمته؛ فاجعل قلبك ممتلئًا بشكرِ رحمةِ الله؛ فهو السميعُ العليمُ الذي يسمع دعاءك ويعلم حالك؛ فارجُ رحمته، واطلبها بالإيمانِ والعمل."}},{"n":7,"reflection":{"text":"«رب السماوات والأرض وما بينهما إن كنتم موقنين»: هو ربُّ السماواتِ والأرضِ وما بينهما، إن كنتم موقنين بذلك؛ ففي هذا تقريرُ ربوبيةِ الله الشاملةِ وربطُها باليقين؛ فوحّد ربَّ السماواتِ والأرض، فمن كان ربًّا لكلِّ شيءٍ يستحقّ العبادة، فحقّق اليقينَ بربوبيةِ الله، فالإقرارُ بربوبيتِه يوجب عبادته.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بربوبيةِ الله الشاملة، وتوحيدُه في العبادة."},"action":{"text":"تأمّل تقريرَ ربوبيةِ الله: هو الله ربُّ السماواتِ والأرضِ وما بينهما، خالقهنّ ومالكهنّ ومدبّرهنّ؛ إن كنتم موقنين بذلك حقَّ اليقين، فوحّدوه واعبدوه «رب السماوات والأرض وما بينهما إن كنتم موقنين»؛ ففي هذا تقريرُ ربوبيةِ الله الشاملةِ لكلِّ شيء، وربطُها باليقين؛ فإذا أيقنتم أنه ربُّ السماواتِ والأرضِ وما بينهما، لزمكم أن تعبدوه وحده؛ فوحّد ربَّ السماواتِ والأرضِ وما بينهما؛ فمن كان ربًّا لكلِّ شيء، خالقًا رازقًا مدبّرًا، فهو المستحقُّ للعبادةِ وحده؛ فحقّق اليقينَ بربوبيةِ الله الشاملة؛ فالإقرارُ بربوبيتِه يوجب توحيدَه في العبادة؛ فأفرده بالعبادةِ كما تفرّد بالربوبية؛ فمن أيقن بأنّ الله ربُّ كلِّ شيء عبده وحده؛ فاجعل يقينك بربوبيةِ الله راسخًا؛ ووحّده في عبادتك؛ فبتوحيدِ الربوبيةِ يلزم توحيدُ الألوهية؛ فاعبد ربَّ السماواتِ والأرض؛ وأخلص له الدين."}},{"n":8,"reflection":{"text":"«لا إله إلا هو يحيي ويميت ربكم ورب آبائكم الأولين»: لا معبودَ بحقٍّ إلا هو، يحيي ويميت، ربّكم وربُّ آبائكم الأوّلين؛ ففي هذا تقريرُ التوحيدِ بالإحياءِ والإماتةِ والربوبية؛ فوحّد الله المحييَ المميتَ ربَّ الجميع، فمن يحيي ويميت يستحقّ العبادةَ وحده، فأخلص له العبادةَ ولا تشرك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"توحيدُ الله المحييِ المميتِ ربِّ الجميع، وإخلاصُ العبادةِ له."},"action":{"text":"تأمّل تقريرَ التوحيد: لا إله إلا هو، لا معبودَ بحقٍّ سواه؛ يحيي الخلقَ ويميتهم، لا يقدر على ذلك غيره؛ ربّكم وربُّ آبائكم الأوّلين، خالقكم وخالقهم «لا إله إلا هو يحيي ويميت ربكم ورب آبائكم الأولين»؛ ففي هذا تقريرُ التوحيدِ بالإحياءِ والإماتةِ والربوبيةِ الشاملة؛ فهو وحده المحييُ المميتُ ربُّ الأوّلين والآخرين؛ فوحّد الله المحييَ المميتَ ربَّ الجميع؛ فمن يحيي ويميت، وهو ربُّك وربُّ آبائك، يستحقّ العبادةَ وحده؛ فأخلص له العبادة؛ ولا تشرك به شيئًا؛ فالإحياءُ والإماتةُ بيدِ الله وحده؛ والربوبيةُ الشاملةُ له وحده؛ فمن كان بهذه الصفاتِ يستحقّ الألوهيةَ والعبادة؛ فوحّده في ربوبيّته وألوهيّته؛ لا إله إلا هو؛ فاعبده وحده؛ وأفرده بالعبادةِ كما تفرّد بالإحياءِ والإماتةِ والربوبية؛ فمن وحّد الله المحييَ المميتَ ربَّ الجميعِ فقد اهتدى؛ فاجعل توحيدك خالصًا لله؛ فهو المعبودُ بحقٍّ لا إله إلا هو."}},{"n":9,"reflection":{"text":"«بل هم في شك يلعبون»: بل المشركون في شكٍّ من الحقِّ يلعبون ويلهون؛ ففي هذا ذمُّ الشكِّ والغفلةِ عن الحق؛ فاحذر الشكَّ في الحقِّ واللعبَ والغفلة، فالشكُّ واللهوُ من صفاتِ المكذّبين، فأيقن بالحقِّ واجدَّ في العمل، ولا تكن من الشاكّين اللاعبين.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بالحق والجدُّ في العمل، وتركُ الشكِّ واللعب."},"action":{"text":"تأمّل ذمَّ الله للمشركين: بل هؤلاء المشركون في شكٍّ وريبٍ من الحقِّ الذي جاءهم، يلعبون ويلهون ولا يجدّون في طلبِ الحقِّ ولا يستيقنونه «بل هم في شك يلعبون»؛ ففي هذا ذمُّ الشكِّ في الحقِّ، واللعبِ واللهوِ والغفلةِ عنه؛ فهم لم يبلغوا مرتبةَ اليقينِ بل هم في شكٍّ ولعب؛ فاحذر الشكَّ في الحقِّ بعد وضوحه؛ واحذر اللعبَ واللهوَ والغفلةَ عن الحقِّ والدين؛ فالشكُّ واللهوُ من صفاتِ المكذّبين المعرضين؛ فأيقن بالحقِّ يقينًا جازمًا؛ والمؤمنون هم الذين آمنوا بالله ورسوله ثم لم يرتابوا؛ وجدَّ في العملِ والطاعة؛ فالدينُ جدٌّ لا لعب؛ ولا تكن من الشاكّين اللاعبين اللاهين؛ بل كن من الموقنين المجدّين في العمل؛ فمن أيقن بالحقِّ وجدَّ في العملِ نجا؛ ومن شكّ فيه ولعب ولها هلك؛ فاجعل قلبك موقنًا بالحقّ؛ وعملك جادًّا في الطاعة؛ فالحياةُ الدنيا دارُ عملٍ وجدّ، لا دارُ لعبٍ ولهو؛ فجدَّ واجتهد، ولا تشكّ ولا تلعب."}}]},{"title":"يومُ الدخانِ والبطشةُ الكبرى، وردُّهم على الرسولِ المبين","range":[10,16],"theme":"التخويفُ بيومِ الدخانِ الذي يغشى الناسَ عذابًا أليمًا فيطلبون كشفَه واعدين بالإيمان، وأنّ الذكرى لا تنفعهم وقد جاءهم رسولٌ مبينٌ فتولّوا عنه ورموه بالتعليمِ والجنون، وأنّ الله يكشف العذابَ قليلًا وهم عائدون، ووعيدُهم بالبطشةِ الكبرى والانتقام","verses":[{"n":10,"reflection":{"text":"«فارتقب يوم تأتي السماء بدخان مبين»: فانتظر يومَ تأتي السماءُ بدخانٍ واضحٍ ظاهر (علامةً أو عذابًا)؛ ففي هذا التخويفُ بيومِ الدخان؛ فاحذر يومَ الدخانِ المخوّف، وترقّب ما يُوعَد به المكذّبون، فالوعيدُ حقٌّ، فاستعدّ بالطاعةِ قبل نزولِ العذاب.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستعدادُ بالطاعة، وترقّبُ ما يُوعَد به المكذّبون."},"action":{"text":"تأمّل التخويفَ بيومِ الدخان: فارتقب وانتظر يا محمدُ يومَ تأتي السماءُ بدخانٍ مبينٍ واضحٍ يعمّ الناس؛ وهو من علاماتِ الساعةِ الكبرى، أو عذابٌ أصابهم في الدنيا بالجدبِ والجوعِ حتى رأوا كهيئةِ الدخان «فارتقب يوم تأتي السماء بدخان مبين»؛ ففي هذا التخويفُ بيومِ الدخانِ المخوّف؛ فأمر الله نبيَّه أن يترقّب هذا اليومَ الذي يأتي فيه العذاب؛ فاحذر أنت يومَ الدخانِ وما فيه من الأهوال؛ وترقّب ما يُوعَد به المكذّبون من العذاب؛ فالوعيدُ حقٌّ واقعٌ لا محالة؛ فاستعدّ للعذابِ والحسابِ بالإيمانِ والطاعةِ والتوبةِ قبل نزوله؛ فمن استعدّ بالطاعةِ نجا، ومن غفل وأصرّ على المعصيةِ هلك؛ فبادر بالتوبةِ والعملِ الصالحِ قبل أن يأتيَ يومُ العذاب؛ فاجعل الوعيدَ حافزًا لك على الطاعةِ والاستعداد؛ فالسعيدُ من اتّعظ بالوعيدِ واستعدّ، والشقيُّ من غفل عنه وأصرّ؛ فاتّق الله، واستعدّ لما يُوعَد به المكذّبون."}},{"n":11,"reflection":{"text":"«يغشى الناس هذا عذاب أليم»: يغشى الدخانُ الناسَ ويحيط بهم، هذا عذابٌ أليم؛ ففي هذا وصفُ شدّةِ عذابِ يومِ الدخان؛ فاحذر العذابَ الأليمَ الذي يغشى الناس، فاعمل لتنجو منه، فالعذابُ محيطٌ بالمكذّبين، فبادر بالطاعةِ والتوبةِ لتنجو.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من العذابِ الأليم، والمبادرةُ بالطاعةِ والتوبةِ للنجاة."},"action":{"text":"تأمّل وصفَ شدّةِ يومِ الدخان: يغشى ذلك الدخانُ الناسَ ويحيط بهم من كلِّ جانب، فيقولون: هذا عذابٌ أليمٌ موجع «يغشى الناس هذا عذاب أليم»؛ ففي هذا وصفُ شدّةِ عذابِ يومِ الدخانِ وإحاطتِه بالناس؛ فيعمّهم الدخانُ ويغشاهم، فيتألّمون ويستغيثون؛ فاحذر العذابَ الأليمَ الذي يغشى الناسَ ويحيط بهم؛ فاعمل لتنجو منه بالإيمانِ والطاعةِ والتوبة؛ فالعذابُ محيطٌ بالمكذّبين المعرضين؛ فبادر بالطاعةِ والتوبةِ قبل أن يحيط بك العذاب؛ فمن آمن وأطاع وتاب نجا من العذاب، ومن كفر وأصرّ أحاط به؛ فاجعل من تصوّرِ هذا العذابِ حافزًا للتوبةِ والعمل؛ فبادر بالإيمانِ والعملِ الصالحِ والتوبةِ قبل فواتِ الأوان؛ فالسعيدُ من عمل لينجو من العذاب، والشقيُّ من فرّط فأحاط به؛ فاتّق الله، واعمل صالحًا، وتب إليه؛ لتنجو من العذابِ الأليمِ الذي يغشى المكذّبين."}},{"n":12,"reflection":{"text":"«ربنا اكشف عنا العذاب إنا مؤمنون»: يقولون عند العذاب: ربّنا اكشف عنّا العذابَ إنا مؤمنون؛ ففي هذا وعدهم بالإيمانِ عند العذاب؛ فاحذر أن تؤخّر الإيمانَ حتى ترى العذابَ فتَعِد به حيث لا ينفع، فالإيمانُ عند العذابِ لا يُقبَل، فبادر بالإيمانِ في زمنِ القبول.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"المبادرةُ بالإيمانِ قبل رؤيةِ العذاب، فالإيمانُ حينئذٍ لا ينفع."},"action":{"text":"تأمّل حالَ المكذّبين عند العذاب: يقولون عند نزولِ العذابِ بهم متضرّعين: ربّنا اكشف عنّا هذا العذابَ فإنا مؤمنون بك ورسولك إن كشفته «ربنا اكشف عنا العذاب إنا مؤمنون»؛ ففي هذا بيانُ وعدِ المكذّبين بالإيمانِ عند رؤيةِ العذاب؛ فلمّا رأوا العذابَ وعدوا بالإيمانِ ليُكشَف عنهم؛ ولكنهم كاذبون أو لا ينفعهم؛ فاحذر أن تؤخّر الإيمانَ والتوبةَ حتى ترى العذابَ أو يحضرك الموتُ فتَعِد بالإيمانِ حيث لا ينفع؛ فالإيمانُ عند معاينةِ العذابِ لا يُقبَل؛ فلمّا رأوا بأسنا قالوا آمنّا بالله وحده... فلم يك ينفعهم إيمانهم لمّا رأوا بأسنا؛ فبادر بالإيمانِ والتوبةِ في زمنِ القبولِ والمهلة؛ قبل أن ترى العذابَ فتَعِد بالإيمانِ فلا ينفعك؛ فمن آمن في زمنِ القبولِ نفعه، ومن أخّر حتى رأى العذابَ لم ينفعه إيمانه؛ فلا تسوّف بالإيمانِ والتوبة؛ بل بادر بهما الآن؛ فالسعيدُ من آمن قبل رؤيةِ العذاب، والخاسرُ من أخّر حتى عاينه."}},{"n":13,"reflection":{"text":"«أنى لهم الذكرى وقد جاءهم رسول مبين»: كيف لهم التذكّرُ والاتّعاظُ (عند العذاب) وقد جاءهم رسولٌ مبينٌ فأعرضوا؟ ففي هذا أنّ التذكّرَ عند العذابِ لا ينفع بعد الإعراض؛ فاغتنم التذكّرَ والاتّعاظَ في زمنِ القبول، فالتذكّرُ عند العذابِ لا ينفع، فاتّعظ بالرسولِ وما جاء به الآن.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاتّعاظُ في زمنِ القبول، فالتذكّرُ عند العذابِ لا ينفع."},"action":{"text":"تأمّل بيانَ أنّ التذكّرَ عند العذابِ لا ينفع: كيف لهم التذكّرُ والاتّعاظُ والإيمانُ عند رؤيةِ العذاب، وقد جاءهم رسولٌ مبينٌ واضحُ الرسالةِ والبيان، فأعرضوا عنه في زمنِ القبول؟ «أنى لهم الذكرى وقد جاءهم رسول مبين»؛ ففي هذا بيانُ أنّ التذكّرَ والاتّعاظَ عند العذابِ لا ينفع بعد الإعراضِ عن الرسولِ في زمنِ القبول؛ فقد جاءهم الرسولُ المبينُ فأعرضوا، فكيف يتذكّرون عند العذابِ حيث لا ينفع؟ فاغتنم أنت التذكّرَ والاتّعاظَ في زمنِ القبولِ والمهلة؛ فالتذكّرُ والاتّعاظُ عند العذابِ أو حضورِ الموتِ لا ينفع؛ فاتّعظ بالرسولِ ﷺ وما جاء به من الوحيِ الآن؛ فقد جاءك الرسولُ المبينُ بالهدى والبيان؛ فاتّبعه واتّعظ به قبل فواتِ الأوان؛ فمن اتّعظ بالرسولِ في زمنِ القبولِ نجا، ومن أعرض عنه حتى رأى العذابَ لم ينفعه تذكّره؛ فبادر بالاتّعاظِ والاتّباعِ للرسول؛ فاغتنم مهلةَ حياتك بالتذكّرِ والعملِ قبل أن يأتيَ وقتٌ لا ينفع فيه التذكّر."}},{"n":14,"reflection":{"text":"«ثم تولوا عنه وقالوا معلم مجنون»: ثم أعرضوا عن الرسولِ وقالوا: معلَّمٌ (يعلّمه بشر) مجنون؛ ففي هذا بيانُ إعراضهم ورميهم الرسولَ بالتهم؛ فاحذر ردَّ الحقِّ برميِ الرسولِ بالتهمِ الباطلة، فرميُ الرسولِ بالجنونِ والتعليمِ من عنادِ المكذّبين، فوقّر الرسولَ واتّبعه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"توقيرُ الرسولِ واتّباعُه، وتركُ ردِّ الحقِّ بالتهم."},"action":{"text":"تأمّل إعراضَ المكذّبين ورميهم الرسول: ثم تولّوا وأعرضوا عن الرسولِ المبينِ بعد أن جاءهم بالبيّنات، وقالوا رادّين لدعوته: هو معلَّمٌ، يعلّمه بشرٌ ما يقول، مجنونٌ لا عقلَ له «ثم تولوا عنه وقالوا معلم مجنون»؛ ففي هذا بيانُ إعراضِ المكذّبين عن الرسول، ورميهم إياه بالتهمِ الباطلةِ المتناقضة؛ فرموه بأنه معلَّمٌ يتلقّى من بشر، ومجنونٌ لا عقلَ له، وهما متناقضتان؛ فاحذر ردَّ الحقِّ برميِ الرسولِ أو أهلِ الحقِّ بالتهمِ الباطلة؛ فرميُ الرسولِ بالجنونِ والسحرِ والكذبِ والتعليمِ من عنادِ المكذّبين وطريقتهم في كلِّ زمان؛ ما يأتيهم من رسولٍ إلا كانوا به يستهزئون؛ فوقّر الرسولَ ﷺ واتّبع ما جاء به؛ ولا تردّ الحقَّ بالتهمِ الباطلةِ على من جاء به؛ فمن وقّر الرسولَ واتّبعه اهتدى، ومن رماه بالتهمِ وأعرض عنه هلك؛ فاجعل موقفك من الرسولِ التوقيرَ والاتّباع، لا الاتّهامَ والإعراض؛ فبتوقيرِ الرسولِ واتّباعِه تُنال الهداية."}},{"n":15,"reflection":{"text":"«إنا كاشفو العذاب قليلا إنكم عائدون»: إنا كاشفو العذابِ عنكم قليلًا، إنكم عائدون إلى الكفر؛ ففي هذا بيانُ أنّ كشفَ العذابِ لا يغيّر المصرّين؛ فاحذر أن تكون ممّن يعود إلى المعصيةِ بعد كشفِ البلاء، فاصدق مع الله في التوبة، فمن عاد إلى الكفرِ بعد كشفِ العذابِ لم ينفعه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الصدقُ في التوبةِ بعد كشفِ البلاء، وتركُ العودةِ إلى المعصية."},"action":{"text":"تأمّل بيانَ أنّ كشفَ العذابِ لا يغيّر المصرّين: إنا كاشفو العذابِ عنكم قليلًا وزمنًا يسيرًا، إنكم عائدون إلى كفركم وتكذيبكم بعد كشفه «إنا كاشفو العذاب قليلا إنكم عائدون»؛ ففي هذا بيانُ أنّ الله قد يكشف العذابَ عن المكذّبين قليلًا، لكنهم يعودون إلى الكفرِ والتكذيب؛ فلا يغيّرهم كشفُ العذاب؛ فوعدهم بالإيمانِ عند العذابِ كاذب؛ فاحذر أن تكون ممّن يعود إلى المعصيةِ والغفلةِ بعد كشفِ البلاءِ عنه؛ فكثيرٌ من الناسِ يتوب ويُقبِل على الله عند البلاء، فإذا كُشِف عنه عاد إلى غفلته ومعصيته؛ فاصدق مع الله في توبتك؛ ولا تعُد إلى المعصيةِ بعد أن نجّاك الله من الشدّة؛ فمن تاب توبةً صادقةً ثبت عليها، ومن كانت توبته عند البلاءِ فقط عاد بعد كشفه؛ فاجعل توبتك صادقةً دائمة، لا مرتبطةً بالبلاءِ وحده؛ فمن عاد إلى الكفرِ والمعصيةِ بعد كشفِ العذابِ لم ينفعه ذلك؛ بل يستحقّ العذابَ الأكبر؛ فاصدق مع الله في الرخاءِ والشدّة؛ فالتوبةُ الصادقةُ ثباتٌ لا عودة."}},{"n":16,"reflection":{"text":"«يوم نبطش البطشة الكبرى إنا منتقمون»: يومَ نبطش البطشةَ الكبرى، إنا منتقمون من المكذّبين؛ ففي هذا الوعيدُ بالبطشةِ الكبرى (يومَ القيامةِ أو بدر)؛ فاحذر البطشةَ الكبرى التي ينتقم الله فيها من المكذّبين، فاعمل لتنجو منها، فانتقامُ الله من المكذّبين حقٌّ، فاتّق الله ولا تكن منهم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من البطشةِ الكبرى، والعملُ للنجاةِ من انتقامِ الله."},"action":{"text":"تأمّل الوعيدَ بالبطشةِ الكبرى: يومَ نبطش البطشةَ الكبرى بالمكذّبين، وهي يومُ القيامة، أو يومُ بدرٍ حيث بطش الله بصناديدِ قريش؛ إنا منتقمون من المكذّبين المعاندين «يوم نبطش البطشة الكبرى إنا منتقمون»؛ ففي هذا الوعيدُ بالبطشةِ الكبرى، وأنّ الله منتقمٌ من المكذّبين؛ فيبطش الله بهم بطشةً عظيمةً، وينتقم منهم؛ فاحذر البطشةَ الكبرى التي ينتقم الله فيها من المكذّبين؛ فاعمل لتنجو منها بالإيمانِ والطاعةِ والتقوى؛ فانتقامُ الله من المكذّبين المعاندين حقٌّ لا محالة؛ إنّ بطشَ ربك لشديد؛ فاتّق الله، ولا تكن من المكذّبين الذين يبطش الله بهم؛ بل كن من المؤمنين المتّقين الناجين؛ فمن آمن واتّقى نجا من البطشةِ الكبرى، ومن كذّب وعاند بطش الله به وانتقم منه؛ فاعمل عملَ الناجين من الإيمانِ والتقوى؛ واحذر عملَ الهالكين من الكفرِ والتكذيب؛ فالنجاةُ في الإيمانِ والتقوى، والهلاكُ في الكفرِ والعناد؛ فبادر بالإيمانِ والطاعةِ لتنجو من انتقامِ الله وبطشتِه الكبرى."}}]},{"title":"موسى وفرعونُ ودعوتُه، وإغراقُ آلِ فرعونَ وزوالُ نعيمهم","range":[17,29],"theme":"ابتلاءُ قومِ فرعونَ بإرسالِ موسى الرسولِ الكريمِ يدعوهم لتحريرِ بني إسرائيلَ وعدمِ العلوِّ على الله ولجوئِه إلى ربه، ودعائِه على قومه المجرمين، وأمرِ الله إياه بالإسراءِ ببني إسرائيلَ وتركِ البحرِ رهوًا لإغراقِ فرعون، وكم تركوا من جنّاتٍ وعيونٍ وزروعٍ ونعمةٍ فما بكت عليهم السماءُ والأرضُ لهوانهم","verses":[{"n":17,"reflection":{"text":"«ولقد فتنا قبلهم قوم فرعون وجاءهم رسول كريم»، ولقد اختبرنا قبل قريشٍ قومَ فرعون، وجاءهم رسولٌ كريمٌ (موسى)؛ ففي هذا التذكيرُ بقصةِ فرعونَ للعبرة؛ فاعتبر بابتلاءِ الله لقومِ فرعونَ بإرسالِ موسى، فالله يبتلي العبادَ بإرسالِ الرسل، فاتّبع الرسولَ الكريمَ ولا تكذّبه، فتكذيبُ الرسلِ سببُ الهلاك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بقصةِ فرعون، واتّباعُ الرسولِ الكريمِ دون تكذيب."},"action":{"text":"تأمّل التذكيرَ بقصةِ فرعونَ للعبرة: ولقد فتنّا واختبرنا قبل قريشٍ قومَ فرعون، وجاءهم رسولٌ كريمٌ في نفسه وحسبه وخلقه، وهو موسى عليه السلام، يدعوهم إلى الله «ولقد فتنا قبلهم قوم فرعون وجاءهم رسول كريم»؛ ففي هذا التذكيرُ بقصةِ فرعونَ وقومه، وابتلاءِ الله لهم بإرسالِ موسى؛ فاختبرهم الله بإرسالِ الرسولِ الكريم إليهم؛ فاعتبر بابتلاءِ الله لقومِ فرعونَ بإرسالِ موسى؛ فالله يبتلي العبادَ بإرسالِ الرسلِ ليتبيّن من يؤمن ومن يكفر؛ فمنهم من هدى الله ومنهم من حقّت عليه الضلالة؛ فاتّبع الرسولَ الكريمَ الذي جاءك، محمدًا ﷺ، ولا تكذّبه؛ فتكذيبُ الرسلِ سببُ الهلاكِ والعذاب؛ فقومُ فرعونَ كذّبوا موسى فأهلكهم الله؛ فاجعل من قصّتهم عبرةً تحملك على الإيمانِ واتّباعِ الرسول؛ فمن اتّبع الرسولَ الكريمَ نجا، ومن كذّبه هلك؛ فوقّر الرسولَ، واتّبعه، ولا تكذّبه؛ فالنجاةُ في اتّباعِ الرسل، والهلاكُ في تكذيبهم."}},{"n":18,"reflection":{"text":"«أن أدوا إلي عباد الله إني لكم رسول أمين»: أن أرسِلوا معي بني إسرائيلَ (عبادَ الله)، إني لكم رسولٌ أمينٌ على الرسالة؛ ففي هذا دعوةُ موسى لتحريرِ المؤمنين وبيانُ أمانتِه؛ فاعلم أنّ الرسلَ أمناءُ على الرسالة، فثق برسلِ الله واتّبعهم، فالأمانةُ من صفاتِ الرسل، فاقتدِ بهم في الأمانةِ والصدق.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثقةُ برسلِ الله واتّباعُهم، والاقتداءُ بأمانتهم."},"action":{"text":"تأمّل دعوةَ موسى: قال موسى لفرعونَ وقومه: أن أدّوا إليّ وأرسِلوا معي عبادَ الله، بني إسرائيلَ، فلا تعذّبوهم ولا تستعبدوهم؛ إني لكم رسولٌ أمينٌ على ما أُرسِلت به من الرسالة، لا أزيد ولا أنقص «أن أدوا إلي عباد الله إني لكم رسول أمين»؛ ففي هذا دعوةُ موسى لتحريرِ بني إسرائيلَ من عبوديةِ فرعون، وبيانُ أمانتِه على الرسالة؛ فطلب موسى إطلاقَ بني إسرائيلَ ليعبدوا الله؛ وأعلن أنه رسولٌ أمينٌ على الرسالة؛ فاعلم أنّ الرسلَ أمناءُ على رسالاتِ الله، يبلّغونها كما أُمِروا؛ فثق برسلِ الله واتّبعهم فيما جاؤوا به؛ فالأمانةُ من أعظمِ صفاتِ الرسلِ وأتباعهم؛ فاقتدِ بالرسلِ في الأمانةِ والصدقِ وأداءِ الحقوق؛ فكن أمينًا في قولك وعملك ومعاملتك؛ فالأمانةُ من صفاتِ المؤمنين؛ والذين هم لأماناتهم وعهدهم راعون؛ فأدِّ الأماناتِ إلى أهلها؛ وكن أمينًا كالرسلِ الكرام؛ فمن اتّصف بالأمانةِ اقتداءً بالرسلِ نال محبّةَ الله والناس."}},{"n":19,"reflection":{"text":"«وأن لا تعلوا على الله إني آتيكم بسلطان مبين»، وألا تتكبّروا على الله بالكفرِ والعناد، إني آتيكم بحجّةٍ واضحة؛ ففي هذا النهيُ عن التكبّرِ على الله؛ فاحذر التكبّرَ على الله بردِّ الحقِّ والعناد، فالعلوُّ على الله سببُ الهلاك، فتواضع لله واقبل الحقَّ ببرهانه، فالكِبرُ على الله أهلك فرعون.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التواضعُ لله وقبولُ الحق، والحذرُ من التكبّرِ على الله."},"action":{"text":"تأمّل نهيَ موسى عن العلوّ على الله: وأن لا تعلوا وتتكبّروا على الله بالكفرِ به وردِّ رسله ومحاربةِ دينه؛ إني آتيكم بسلطانٍ مبينٍ وحجّةٍ واضحةٍ على صدقِ رسالتي «وأن لا تعلوا على الله إني آتيكم بسلطان مبين»؛ ففي هذا النهيُ عن التكبّرِ والعلوِّ على الله، والأمرُ بقبولِ الحقِّ ببرهانه؛ فنهى موسى فرعونَ عن التكبّرِ على الله وردِّ الحق؛ فاحذر التكبّرَ والعلوَّ على الله بردِّ الحقِّ والعنادِ ومحاربةِ الدين؛ فالعلوُّ على الله والتكبّرُ عن الحقِّ سببُ الهلاك؛ فقد أهلك الله فرعونَ بعلوّه وتكبّره؛ تلك الدارُ الآخرةُ نجعلها للذين لا يريدون علوًّا في الأرضِ ولا فسادًا؛ فتواضع لله، واقبل الحقَّ ببرهانه ودليله؛ ولا تستكبر عن الحقِّ ولو خالف هواك؛ فالكِبرُ على الله وردُّ الحقِّ أهلك فرعونَ ومن قبله؛ فمن تواضع لله وقبل الحقَّ نجا، ومن تكبّر عليه وردّ الحقَّ هلك؛ فاطرح الكِبرَ والعلوّ؛ وتواضع لله؛ واقبل الحقَّ ببرهانه؛ فالتواضعُ سبيلُ النجاة، والكِبرُ سبيلُ الهلاك."}},{"n":20,"reflection":{"text":"«وإني عذت بربي وربكم أن ترجمون»، وإني لجأت واستعذت بربي وربّكم أن ترجموني وتقتلوني؛ ففي هذا لجوءُ موسى إلى الله من كيدِ الطغاة؛ فالجأ إلى الله واستعذ به من شرِّ الأعداء، فالله يعصم من التجأ إليه، فاجعل عياذك بالله من كلِّ شر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اللجوءُ إلى الله والاستعاذةُ به من شرِّ الأعداء."},"action":{"text":"تأمّل لجوءَ موسى إلى الله: وإني عذت واعتصمت ولجأت بربي وربّكم أن ترجموني بالحجارةِ فتقتلوني أو تشتموني «وإني عذت بربي وربكم أن ترجمون»؛ ففي هذا لجوءُ موسى إلى الله والاستعاذةُ به من كيدِ الطغاةِ وشرّهم؛ فلمّا خاف موسى بطشَهم لجأ إلى ربه واعتصم به؛ فالجأ أنت إلى الله واستعذ به من شرِّ الأعداءِ والأشرار؛ فالله يعصم ويحفظ من التجأ إليه واعتصم به؛ فمن عاذ بالله أعاذه، ومن لجأ إليه حماه؛ فاجعل عياذك والتجاءك بالله من كلِّ شرٍّ ومن كلِّ عدوٍّ باغٍ؛ فأعوذ بكلماتِ الله التامّاتِ من شرِّ ما خلق؛ فمن استعاذ بالله بصدقٍ كفاه شرَّ الأعداء؛ فلا تخف بطشَ الطغاةِ ما دمت معتصمًا بالله؛ فالله أقوى منهم وأعظم؛ فالجأ إليه، واعتصم به، واستعذ به؛ فهو خيرُ حافظٍ وهو أرحمُ الراحمين؛ فمن كان الله معاذه ومعتصمه لم يضرّه كيدُ الأعداء."}},{"n":21,"reflection":{"text":"«وإن لم تؤمنوا لي فاعتزلون»، وإن لم تصدّقوني فاتركوني ولا تؤذوني؛ ففي هذا طلبُ موسى الكفَّ عن أذاه؛ فاعلم أنّ الداعيةَ يطلب الحدَّ الأدنى (الكفَّ عن الأذى) إن لم يستجيبوا، فادعُ إلى الحقِّ بحكمة، وإن لم يستجيبوا فاطلب السلامةَ من أذاهم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحكمةُ في الدعوة، وطلبُ السلامةِ من أذى المعرضين."},"action":{"text":"تأمّل حكمةَ موسى في دعوته: وإن لم تؤمنوا لي وتصدّقوني، فاعتزلوني واتركوني ولا تتعرّضوا لي بأذًى ولا قتل؛ فطلب الكفَّ عن أذاه إن لم يستجيبوا «وإن لم تؤمنوا لي فاعتزلون»؛ ففي هذا بيانُ حكمةِ موسى في دعوته، وطلبِه الحدَّ الأدنى، الكفَّ عن الأذى، إن لم يستجيبوا للإيمان؛ فدعاهم أولًا إلى الإيمان، فإن أبوا فليتركوه ولا يؤذوه؛ فاعلم أنّ الداعيةَ الحكيمَ يطلب الحدَّ الأدنى إن لم يستجيبوا لدعوته؛ فادعُ إلى الحقِّ بالحكمةِ والموعظةِ الحسنة؛ فإن لم يستجيبوا فاطلب السلامةَ من أذاهم؛ ولا تتعرّض للفتنةِ والأذى بلا فائدة؛ فالمؤمنُ كيّسٌ فطن، يدفع الشرَّ بأخفِّ الوسائل؛ فبلّغ الحقَّ بحكمة؛ فمن استجاب فالحمد لله، ومن أبى فاطلب السلامةَ منه؛ ولا تحمّل نفسك ما لا تطيق؛ فاجعل دعوتك بالحكمة، وطلبك للسلامةِ من الأذى عند الإعراض؛ فبالحكمةِ في الدعوةِ وطلبِ السلامةِ يتحقّق البلاغُ مع أقلِّ ضرر."}},{"n":22,"reflection":{"text":"«فدعا ربه أن هؤلاء قوم مجرمون»: فدعا موسى ربه أنّ هؤلاء قومٌ مجرمون (مستحقّون العذاب)؛ ففي هذا لجوءُ موسى إلى الله بعد إصرارهم؛ فالجأ إلى الله بالدعاءِ بعد بذلِ الدعوة، فإذا أعرض المدعوّون وأصرّوا فوّض أمرهم إلى الله، فالدعاءُ سلاحُ المؤمنِ بعد بذلِ الأسباب.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اللجوءُ إلى الله بالدعاءِ بعد بذلِ الدعوةِ وإصرارِ المعرضين."},"action":{"text":"تأمّل لجوءَ موسى إلى الله: فلمّا أصرّ فرعونُ وقومه على الكفرِ والعنادِ وأذى موسى، دعا موسى ربه شاكيًا: أنّ هؤلاء قومٌ مجرمون مستحقّون للعذابِ والعقوبة «فدعا ربه أن هؤلاء قوم مجرمون»؛ ففي هذا لجوءُ موسى إلى الله بالدعاءِ بعد إصرارِ قومه على الكفر؛ فلمّا يئس من إيمانهم رفع أمرهم إلى الله بالدعاء؛ فالجأ أنت إلى الله بالدعاءِ بعد بذلِ الدعوةِ والنصح؛ فإذا أعرض المدعوّون وأصرّوا على الباطلِ بعد بلوغِ الحجّة، فوّض أمرهم إلى الله وادعه؛ فالدعاءُ سلاحُ المؤمنِ بعد بذلِ الأسبابِ من الدعوةِ والنصح؛ فموسى دعا ربه بعد أن بلّغ ونصح؛ ونوحٌ قال ربِّ إني دعوت قومي ليلًا ونهارًا فلم يزدهم دعائي إلا فرارًا؛ فابذل الدعوةَ والنصح؛ ثم فوّض الأمرَ إلى الله بالدعاء؛ فمن بذل الأسبابَ ثم لجأ إلى الله بالدعاءِ كفاه الله؛ فاجعل الدعاءَ ملجأك بعد بذلِ الجهد؛ فالله يجيب المضطرَّ إذا دعاه ويكشف السوء."}},{"n":23,"reflection":{"text":"«فأسر بعبادي ليلا إنكم متبعون»: قال الله لموسى: فأسرِ بعبادي (بني إسرائيل) ليلًا، إنكم متَّبعون (سيتبعكم فرعون)؛ ففي هذا أمرُ الله موسى بالخروجِ وبيانُ التدبيرِ الإلهي؛ فاعلم أنّ الله يدبّر لأوليائه النجاة، فثق بتدبيرِ الله وامتثل أمره، فمن أطاع الله واتّبع أمره نجّاه الله بتدبيره.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثقةُ بتدبيرِ الله لأوليائه، وامتثالُ أمره."},"action":{"text":"تأمّل أمرَ الله لموسى بالخروج: فاستجاب الله دعاءَ موسى، وقال له: فأسرِ بعبادي المؤمنين، بني إسرائيلَ، ليلًا سرًّا؛ إنكم متَّبعون، سيتبعكم فرعونُ وجنوده «فأسر بعبادي ليلا إنكم متبعون»؛ ففي هذا أمرُ الله موسى بالخروجِ ببني إسرائيلَ ليلًا، وبيانُ تدبيرِ الله لنجاتهم وإهلاكِ عدوّهم؛ فأمر الله موسى بالخروجِ سرًّا، وأخبره أنهم سيُتبَعون، لتتمّ الحكمةُ في إغراقِ فرعون؛ فاعلم أنّ الله يدبّر لأوليائه المؤمنين النجاةَ من أعدائهم؛ فثق بتدبيرِ الله لك؛ وامتثل أمره وإن لم تعلم الحكمةَ كلَّها؛ فموسى امتثل أمرَ الله بالخروجِ ليلًا؛ فمن أطاع الله واتّبع أمره نجّاه الله بتدبيره ولطفه؛ ومن يتّق الله يجعل له مخرجًا ويرزقه من حيث لا يحتسب؛ فامتثل أمرَ الله، وثق بتدبيره ولطفه؛ فإنّ الله يدبّر لأوليائه ما فيه نجاتهم؛ فمن توكّل على الله وأطاع أمره كفاه ونجّاه؛ فاجعل ثقتك بتدبيرِ الله، وامتثالك لأمره؛ فبهما تُنال النجاة."}},{"n":24,"reflection":{"text":"«واترك البحر رهوا إنهم جند مغرقون»، واترك البحرَ ساكنًا منفرجًا (بعد أن جاوزته)، إنهم جندٌ مغرقون؛ ففي هذا بيانُ تدبيرِ الله لإغراقِ فرعون؛ فاعلم أنّ الله يهلك أعداءه بتدبيره العجيب، فثق بأنّ الله ينصر أولياءه ويهلك أعداءهم، فتدبيرُ الله لأوليائه بالنجاةِ ولأعدائهم بالهلاك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بأنّ الله ينصر أولياءه ويهلك أعداءهم بتدبيره."},"action":{"text":"تأمّل تدبيرَ الله لإغراقِ فرعون: قال الله لموسى: واترك البحرَ، بعد أن جاوزته أنت وقومك، رهوًا، أي ساكنًا منفرجًا على حاله، لا تأمره أن يعود؛ إنّ فرعونَ وجنوده إذا دخلوه جندٌ مغرقون «واترك البحر رهوا إنهم جند مغرقون»؛ ففي هذا بيانُ تدبيرِ الله العجيبِ لإغراقِ فرعونَ وجنوده؛ فأمر الله موسى أن يترك البحرَ منفرجًا ليدخله فرعونُ فيُغرَق؛ فاعلم أنّ الله يهلك أعداءه بتدبيره العجيبِ الذي لا يخطر على بال؛ ففلق البحرَ لموسى، ثم أغرق فيه فرعون؛ فثق بأنّ الله ينصر أولياءه المؤمنين، ويهلك أعداءهم الكافرين، بتدبيره ولطفه؛ فتدبيرُ الله لأوليائه بالنجاةِ والفرج، ولأعدائهم بالهلاكِ والعذاب؛ فلا تخف من أعدائك ما دمت متوكّلًا على الله؛ فإنّ الله يدبّر لك النجاة، ولأعدائك الهلاك؛ فمن توكّل على الله نصره وأهلك عدوّه؛ فاجعل ثقتك بتدبيرِ الله ونصره؛ فالعاقبةُ لأوليائه، والهلاكُ لأعدائه؛ فثق بنصرِ الله لأوليائه، وإهلاكِه لأعدائهم."}},{"n":25,"reflection":{"text":"«كم تركوا من جنات وعيون»: كم ترك فرعونُ وقومه من بساتينَ وعيونٍ بعد إغراقهم؛ ففي هذا بيانُ زوالِ نعيمِ الطغاة؛ فاعتبر بزوالِ نعيمِ الطغاةِ الذين تركوا كلَّ شيء، فالدنيا زائلةٌ لا تبقى لأحد، فلا تغترّ بنعيمها، فمهما جمعت من الدنيا تركتها.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بزوالِ نعيمِ الطغاة، وعدمُ الاغترارِ بالدنيا."},"action":{"text":"تأمّل زوالَ نعيمِ فرعونَ وقومه: كم تركوا بعد إغراقهم من جنّاتٍ وبساتينَ عامرة، وعيونٍ جاريةٍ من الماء «كم تركوا من جنات وعيون»؛ ففي هذا بيانُ زوالِ نعيمِ الطغاةِ وما جمعوه من الدنيا؛ فبعد أن كانوا في نعيمٍ وجنّاتٍ وعيون، أغرقهم الله وتركوا كلَّ ذلك؛ فاعتبر بزوالِ نعيمِ الطغاةِ والمترفين الذين تركوا كلَّ ما جمعوه؛ فالدنيا زائلةٌ لا تبقى لأحد؛ وما جمعوه من الجنّاتِ والعيونِ والأموالِ تركوه وراءهم؛ فلا تغترّ بنعيمِ الدنيا وزينتها؛ فمهما جمعت منها فإنك تاركها؛ ولقد جئتمونا فرادى كما خلقناكم أوّلَ مرّةٍ وتركتم ما خوّلناكم وراء ظهوركم؛ فما تجمعه من الدنيا تتركه عند الموت؛ فاجعل همّك ما يبقى لك عند الله، لا ما يفنى ويُترَك؛ فالدنيا دارُ ممرٍّ لا دارُ مقرّ؛ فمن اعتبر بزوالِ الدنيا عن أهلها زهد فيها وعمل للآخرة؛ فاعتبر بمصارعِ الطغاةِ وزوالِ نعيمهم؛ ولا تغترّ بالدنيا الزائلة."}},{"n":26,"reflection":{"text":"«وزروع ومقام كريم»، وتركوا زروعًا ومنازلَ حسنةً كريمة؛ ففي هذا تمامُ بيانِ ما تركه الطغاة؛ فاعتبر بما تركه الطغاةُ من الزروعِ والمنازل، فكلُّ ما في الدنيا يُترَك، فاعمل لما يبقى لك في الآخرة، ولا تجعل الدنيا غايتك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بما يُترَك من الدنيا، والعملُ لما يبقى في الآخرة."},"action":{"text":"تأمّل تمامَ ما تركه فرعونُ وقومه: وتركوا زروعًا ومزارعَ خصبة، ومقامًا كريمًا، منازلَ حسنةً ومجالسَ بهيّةً كانوا يتنعّمون فيها «وزروع ومقام كريم»؛ ففي هذا تمامُ بيانِ ما تركه الطغاةُ من نعيمِ الدنيا؛ فتركوا الزروعَ والمنازلَ الكريمةَ التي كانوا فيها؛ فاعتبر بما تركه الطغاةُ من الزروعِ والمنازلِ والنعيم؛ فكلُّ ما في الدنيا يُترَك ويُخلَّف؛ فلا تبقى الدنيا لأحد؛ فاعمل لما يبقى لك في الآخرة، لا لما يفنى ويُترَك من الدنيا؛ ولا تجعل الدنيا غايتك ومطلبك الأكبر؛ فما عند الله خيرٌ وأبقى؛ فمن جعل الدنيا غايته خسر عند الموت؛ ومن جعلها وسيلةً للآخرةِ ربح؛ فاجعل الدنيا مزرعةً للآخرة؛ واعمل فيها لما يبقى لك عند الله؛ فمهما جمعت من الدنيا تركته؛ وما يبقى لك إلا عملك الصالح؛ فاعمل صالحًا يبقَ لك، ولا تحرص على دنيا تُترَك؛ فالعاقلُ يعمل للباقي، لا للفاني."}},{"n":27,"reflection":{"text":"«ونعمة كانوا فيها فاكهين»، ونعمةٍ ومتاعٍ كانوا فيه متنعّمين متلذّذين؛ ففي هذا بيانُ زوالِ نعمةِ الطغاة؛ فاعتبر بزوالِ نعمةِ الطغاةِ الذين كانوا في تنعّمٍ ثم زال عنهم، فالنعمةُ زائلة، فاشكر نعمةَ الله واستعملها في طاعته، ولا تغترّ بها.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ النعمةِ واستعمالُها في الطاعة، والاعتبارُ بزوالها عن الطغاة."},"action":{"text":"تأمّل زوالَ نعمةِ فرعونَ وقومه: ونعمةٍ ومتاعٍ ورفاهيةٍ كانوا فيها فاكهين، متنعّمين متلذّذين ناعمين، ثم زال عنهم كلُّ ذلك بالإغراق «ونعمة كانوا فيها فاكهين»؛ ففي هذا بيانُ زوالِ نعمةِ الطغاةِ ومتاعهم؛ فبعد أن كانوا في نعمةٍ ومتاعٍ وتلذّذ، أهلكهم الله وزال عنهم كلُّ ذلك؛ فاعتبر بزوالِ نعمةِ الطغاةِ والمترفين الذين كانوا في تنعّمٍ ثم زال عنهم؛ فالنعمةُ زائلةٌ لا تدوم؛ فلا تغترّ بنعمةِ الدنيا ومتاعها؛ بل اشكر نعمةَ الله عليك، واستعملها في طاعته؛ فمن شكر النعمةَ واستعملها في الطاعةِ بورك له فيها؛ ومن كفرها وبطر بها زالت عنه أو صارت وبالًا عليه؛ ولئن شكرتم لأزيدنّكم ولئن كفرتم إنّ عذابي لشديد؛ فاجعل نعمَ الله عونًا على طاعته، لا سببًا للبطرِ والغفلة؛ واعلم أنّ النعمةَ زائلة؛ فلا تغترّ بها؛ بل اشكرها، واستعملها في مرضاةِ الله؛ فمن اعتبر بزوالِ نعمةِ الطغاةِ شكر نعمته واستعملها في الطاعة."}},{"n":28,"reflection":{"text":"«كذلك وأورثناها قوما آخرين»: كذلك كان أمرهم، وأورثنا نعيمَهم قومًا آخرين؛ ففي هذا بيانُ أنّ الدنيا تنتقل من قومٍ إلى قوم؛ فاعتبر بانتقالِ نعيمِ الدنيا بين الناس، فالدنيا دُوَلٌ بين الناسِ لا تبقى لأحد، فلا تحرص عليها، بل اعمل للآخرةِ الباقية.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بانتقالِ الدنيا بين الناس، والعملُ للآخرةِ الباقية."},"action":{"text":"تأمّل بيانَ انتقالِ نعيمِ الدنيا: كذلك كان أمرُ فرعونَ وقومه من الإهلاكِ وزوالِ النعيم؛ وأورثنا تلك الجنّاتِ والعيونَ والزروعَ والنعيمَ قومًا آخرين، بني إسرائيلَ أو غيرهم «كذلك وأورثناها قوما آخرين»؛ ففي هذا بيانُ أنّ الدنيا ونعيمها تنتقل من قومٍ إلى قوم، لا تبقى لأحد؛ فأورث الله نعيمَ فرعونَ قومًا آخرين؛ فاعتبر بانتقالِ نعيمِ الدنيا بين الناسِ جيلًا بعد جيل؛ فالدنيا دُوَلٌ يتداولها الناس؛ وتلك الأيّامُ نداولها بين الناس؛ فلا تبقى الدنيا لأحد؛ فما كان لقومٍ صار لآخرين؛ فلا تحرص على الدنيا الزائلةِ المتنقّلة؛ بل اعمل للآخرةِ الباقيةِ التي لا تنتقل؛ فمن جعل الدنيا غايته خسرها عند الموت، وورثها غيره؛ ومن عمل للآخرةِ ربح ما يبقى له؛ فاجعل همّك الآخرةَ الباقية، لا الدنيا المتنقّلة؛ فالدنيا لمن بعدك، والآخرةُ لك إن عملت لها؛ فاعمل للباقي، ولا تغترّ بالفاني المتنقّل؛ فمن اعتبر بانتقالِ الدنيا زهد فيها وعمل لآخرته."}},{"n":29,"reflection":{"text":"«فما بكت عليهم السماء والأرض وما كانوا منظرين»: فما بكت على فرعونَ وقومه السماءُ والأرضُ (لهوانهم على الله)، وما كانوا مُمهَلين؛ ففي هذا بيانُ هوانِ الطغاةِ على الله؛ فاحذر أن تهون على الله بالكفرِ والطغيان، فاعمل عملًا صالحًا يرفع قدرك عند الله، فمن هان على الله لم يُؤسَف عليه، ومن كرُم عليه بكت عليه السماءُ.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الهوانِ على الله بالطغيان، والعملُ لرفعةِ القدرِ عنده."},"action":{"text":"تأمّل بيانَ هوانِ الطغاةِ على الله: فما بكت على فرعونَ وقومه بعد هلاكهم السماءُ والأرض، لهوانهم على الله وعدمِ قدرهم عنده؛ وما كانوا مُنظَرين مُمهَلين، بل أُخِذوا بغتة «فما بكت عليهم السماء والأرض وما كانوا منظرين»؛ ففي هذا بيانُ هوانِ الطغاةِ على الله، وأنه لم يُؤسَف عليهم؛ فالمؤمنُ الصالحُ إذا مات بكى عليه أهلُ السماءِ والأرض، أو مصلّاه ومصعدُ عمله؛ أمّا الكافرُ الطاغيةُ فلا يُؤسَف عليه ولا يُبكى؛ فاحذر أن تهون على الله بالكفرِ والطغيانِ والمعاصي؛ فمن هان على الله لم يُؤسَف عليه ولم يُبكَ عليه؛ فاعمل عملًا صالحًا يرفع قدرك عند الله ويكرمك عنده؛ فالمؤمنُ الصالحُ كريمٌ على الله؛ إنّ العبدَ المؤمنَ إذا مات بكى عليه مصلّاه من الأرضِ ومصعدُ عمله من السماء؛ فاطلب الكرامةَ عند الله بالإيمانِ والعملِ الصالحِ والتقوى؛ ولا تكن من الطغاةِ الذين يهونون على الله فلا يُؤسَف عليهم؛ فمن كرُم على الله بإيمانه وعمله رُفِع قدره، ومن هان عليه بطغيانه لم يُبكَ عليه؛ فاعمل لرفعةِ قدرك عند الله؛ فالكرامةُ عنده بالتقوى والعملِ الصالح."}}]},{"title":"نجاةُ بني إسرائيلَ من فرعون، واصطفاؤهم وابتلاؤهم بالآيات","range":[30,33],"theme":"تنجيةُ بني إسرائيلَ من العذابِ المهينِ من فرعونَ العالي المسرف، واصطفاؤهم على علمٍ على عالمي زمانهم، وإيتاؤهم من الآياتِ والنعمِ ما فيه ابتلاءٌ مبينٌ يميّز الشاكرَ من الكافر","verses":[{"n":30,"reflection":{"text":"«ولقد نجينا بني إسرائيل من العذاب المهين»، ولقد نجّينا بني إسرائيلَ من العذابِ المذلِّ (استعبادِ فرعون)؛ ففي هذا بيانُ نجاةِ المؤمنين من العذاب؛ فاعلم أنّ الله ينجّي المؤمنين من الذلِّ والعذاب، فالجأ إلى الله لينجّيك، فمن التجأ إلى الله نجّاه من كلِّ ذلٍّ وعذاب.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الرجاءُ في تنجيةِ الله للمؤمنين، والالتجاءُ إليه."},"action":{"text":"تأمّل نجاةَ بني إسرائيل: ولقد نجّينا بني إسرائيلَ المؤمنين من العذابِ المهينِ المذلّ، من استعبادِ فرعونَ وتقتيلِه أبناءهم واستحياءِ نسائهم «ولقد نجينا بني إسرائيل من العذاب المهين»؛ ففي هذا بيانُ نجاةِ المؤمنين من العذابِ والذلّ؛ فبعد أن كانوا في عذابٍ مهينٍ من فرعون، نجّاهم الله منه؛ فاعلم أنّ الله ينجّي عباده المؤمنين من الذلِّ والعذابِ والشدائد؛ فالجأ إلى الله لينجّيك من كلِّ ذلٍّ وعذابٍ وشدّة؛ فمن التجأ إلى الله بصدقٍ نجّاه؛ فالله وليُّ المؤمنين ينجّيهم؛ ونجّينا الذين آمنوا وكانوا يتّقون؛ فاجعل الله ملجأك ومنجاك؛ ولا تيأس من تنجيةِ الله ولو اشتدّ الذلُّ والعذاب؛ فكم من أمّةٍ مستضعفةٍ نجّاها الله وأعزّها؛ فأحسن الظنَّ بالله، وارجُ تنجيته؛ فمن صدق اللجوءَ إلى الله نجّاه وأعزّه؛ فالتنجيةُ من الذلِّ والعذابِ ثمرةُ الإيمانِ واللجوءِ إلى الله؛ فآمن والجأ إلى الله، وارجُ تنجيته؛ فإنه منجّي المؤمنين."}},{"n":31,"reflection":{"text":"«من فرعون إنه كان عاليا من المسرفين»: نجّيناهم من فرعون، إنه كان متكبّرًا متجاوزًا حدَّه في الطغيان؛ ففي هذا ذمُّ العلوِّ والإسراف؛ فاحذر العلوَّ على الخلقِ والإسرافَ في الطغيان، فإنه سببُ الهلاك، فتواضع والزم حدودَ الله، فالعلوُّ والإسرافُ أهلكا فرعون.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من العلوِّ والإسرافِ في الطغيان، والتواضعُ ولزومُ الحدود."},"action":{"text":"تأمّل ذمَّ فرعون: نجّينا بني إسرائيلَ من فرعونَ الذي كان عاليًا متكبّرًا متجبّرًا على الخلق، من المسرفين المتجاوزين حدودَهم في الطغيانِ والكفرِ والظلم «من فرعون إنه كان عاليا من المسرفين»؛ ففي هذا ذمُّ العلوِّ والتكبّرِ والإسرافِ في الطغيان؛ فكان فرعونُ عاليًا متكبّرًا على عبادِ الله، مسرفًا في الطغيانِ والظلم؛ فاحذر العلوَّ والتكبّرَ على الخلق، والإسرافَ في الطغيانِ والظلمِ والمعاصي؛ فإنّ العلوَّ والإسرافَ سببُ الهلاكِ والعذاب؛ فقد أهلك الله فرعونَ بعلوّه وإسرافه؛ تلك الدارُ الآخرةُ نجعلها للذين لا يريدون علوًّا في الأرضِ ولا فسادًا؛ فتواضع لله وللخلق؛ والزم حدودَ الله ولا تتجاوزها؛ ولا تسرف في الطغيانِ والمعاصي؛ فالعلوُّ على الخلقِ والإسرافُ في الطغيانِ أهلكا فرعونَ ومن قبله؛ فمن تواضع ولزم حدودَ الله نجا، ومن علا وأسرف هلك؛ فاجتنب العلوَّ والإسراف؛ والزم التواضعَ وحدودَ الله؛ فالتواضعُ سبيلُ النجاة، والعلوُّ والإسرافُ سبيلُ الهلاك."}},{"n":32,"reflection":{"text":"«ولقد اخترناهم على علم على العالمين»، ولقد اخترنا بني إسرائيلَ على علمٍ منّا على عالمي زمانهم (بإرسالِ الرسلِ فيهم)؛ ففي هذا بيانُ اصطفاءِ الله لبني إسرائيلَ في زمانهم؛ فاعلم أنّ الاصطفاءَ من الله بحكمته وعلمه، فاشكر نعمةَ الله إن اصطفاك، وحقّق شكرها بالطاعة، فالاصطفاءُ نعمةٌ تُشكَر بالعمل.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمةِ الاصطفاءِ بالطاعة، وإدراكُ أنه بعلمِ الله وحكمته."},"action":{"text":"تأمّل اصطفاءَ بني إسرائيل: ولقد اخترنا واصطفينا بني إسرائيلَ على علمٍ منّا بحالهم واستحقاقهم في زمانهم، على عالمي زمانهم، بأن أرسلنا فيهم الرسلَ وأنزلنا عليهم الكتب وفضّلناهم «ولقد اخترناهم على علم على العالمين»؛ ففي هذا بيانُ اصطفاءِ الله لبني إسرائيلَ على عالمي زمانهم بكثرةِ الأنبياءِ فيهم؛ فاختارهم الله على علمٍ منه بحكمته؛ فاعلم أنّ الاصطفاءَ والاختيارَ من الله بحكمته وعلمه؛ فهو أعلمُ حيث يجعل فضله واصطفاءه؛ فإن اصطفاك الله بنعمةٍ، من إيمانٍ أو علمٍ أو دينٍ أو هداية، فاشكرها؛ وحقّق شكرها بالطاعةِ والعملِ الصالح؛ فالاصطفاءُ والنعمةُ تُشكَر بالعملِ لا بالدعوى؛ فبنو إسرائيلَ اصطُفوا ثم لمّا لم يشكروا وبدّلوا سُلِبوا الفضلَ وحلّ بهم الذلّ؛ فاجعل شكرك لنعمِ الله بالطاعةِ والعملِ الصالح؛ فمن شكر نعمةَ الاصطفاءِ بالطاعةِ دامت له، ومن كفرها سُلِبها؛ فاحذر أن تُنعِم عليك النعمةُ فتكفرها؛ بل اشكرها بالعمل؛ فبشكرِ النعمةِ تدوم وتزيد."}},{"n":33,"reflection":{"text":"«وآتيناهم من الآيات ما فيه بلاء مبين»، وأعطيناهم من الآياتِ والنعمِ ما فيه اختبارٌ واضح؛ ففي هذا بيانُ أنّ النعمَ والآياتِ ابتلاء؛ فاعلم أنّ نعمَ الله وآياته ابتلاءٌ لك: أتشكر أم تكفر؟ فاشكر نعمَ الله واتّعظ بآياته، فالنعمُ والآياتُ اختبارٌ يميّز الشاكرَ من الكافر.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمِ الله والاتّعاظُ بآياته، وإدراكُ أنها ابتلاء."},"action":{"text":"تأمّل بيانَ أنّ النعمَ ابتلاء: وآتينا بني إسرائيلَ من الآياتِ والمعجزاتِ والنعمِ ما فيه بلاءٌ مبينٌ واختبارٌ واضح: أيشكرون أم يكفرون؟ أيؤمنون أم يجحدون؟ «وآتيناهم من الآيات ما فيه بلاء مبين»؛ ففي هذا بيانُ أنّ النعمَ والآياتِ التي أعطاها الله بني إسرائيلَ كانت ابتلاءً واختبارًا لهم؛ ففُلِق لهم البحرُ، وأُنزِل عليهم المنُّ والسلوى، وظُلّلوا بالغمام؛ كلُّ ذلك ابتلاءٌ واختبار؛ فاعلم أنّ نعمَ الله وآياته ابتلاءٌ لك واختبار: أتشكر أم تكفر؟ أتطيع أم تعصي؟ فلنبلونّكم؛ ونبلوكم بالشرِّ والخيرِ فتنة؛ فاشكر نعمَ الله واتّعظ بآياته؛ واستعمل النعمَ في طاعته؛ فالنعمُ والآياتُ اختبارٌ يميّز الشاكرَ من الكافر، والمطيعَ من العاصي؛ فمن شكر النعمةَ واتّعظ بالآيةِ نجح في الاختبار، ومن كفرها وأعرض عن الآيةِ خسر؛ فاجعل نعمَ الله وآياته سببًا للشكرِ والاتّعاظِ والطاعة؛ فبها تنجح في ابتلاءِ الله؛ فمن شكر النعمةَ وانتفع بالآيةِ فاز، ومن بطر وأعرض هلك."}}]},{"title":"إنكارُ المكذّبين للبعث، وإهلاكُ قومِ تبّع، وأنّ الخلقَ بالحق","range":[34,39],"theme":"حكايةُ إنكارِ المشركين للبعثِ وطلبِهم إحياءَ آبائهم تعجيزًا، وتخويفُهم بإهلاكِ قومِ تبّعٍ ومن قبلهم لإجرامهم، وأنّ الله ما خلق السماواتِ والأرضَ لاعبًا بل بالحقِّ لحكمةٍ لا يعلمها أكثرُ الناس","verses":[{"n":34,"reflection":{"text":"«إن هؤلاء ليقولون»: إنّ هؤلاء المشركين ليقولون منكرين البعث؛ ففي هذا حكايةُ إنكارهم للبعث؛ فاحذر إنكارَ البعثِ الذي أنكره المشركون، فالبعثُ حقٌّ لا ريب فيه، فأيقن به واعمل له، فمن أنكر البعثَ عطّل الحكمةَ من الخلق.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بالبعثِ والعملُ له، وتركُ إنكارِ المشركين."},"action":{"text":"تأمّل حكايةَ إنكارِ المشركين للبعث: إنّ هؤلاء المشركين من قريشٍ ليقولون قولًا باطلًا ينكرون به البعثَ والنشور «إن هؤلاء ليقولون»؛ ففي هذا حكايةُ قولِ المشركين المنكرين للبعث؛ فأخبر الله عنهم أنهم يقولون منكرين إعادةَ الخلق؛ فاحذر إنكارَ البعثِ الذي أنكره المشركون؛ فالبعثُ حقٌّ لا ريب فيه، قامت عليه الأدلّةُ والبراهين؛ فأيقن بالبعثِ والنشورِ والحسابِ والجزاء؛ واعمل له عملًا صالحًا؛ فمن أنكر البعثَ عطّل الحكمةَ من خلقِ الله؛ أفحسبتم أنما خلقناكم عبثًا وأنكم إلينا لا تُرجَعون؛ فالله لم يخلقِ الخلقَ عبثًا، بل ليبعثهم ويجزيهم؛ فأيقن بلقاءِ الله، واعمل لذلك اليوم؛ فمن أيقن بالبعثِ استعدّ له بالعمل، ومن أنكره غفل وضلّ؛ فاجعل يقينك بالبعثِ حافزًا لك على العمل."}},{"n":35,"reflection":{"text":"«إن هي إلا موتتنا الأولى وما نحن بمنشرين»: يقولون: ما هي إلا موتتُنا الأولى وما نحن بمبعوثين؛ ففي هذا بيانُ إنكارهم للنشور؛ فاحذر إنكارَ النشورِ بعد الموت، فالله قادرٌ على إعادةِ الخلقِ كما بدأه، فأيقن بالنشورِ واستعدّ له، فإنكارُ النشورِ جهلٌ بقدرةِ الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بالنشورِ والاستعدادُ له، وإدراكُ قدرةِ الله على الإعادة."},"action":{"text":"تأمّل بيانَ إنكارِ المشركين للنشور: يقول المشركون: ما هي إلا موتتُنا الأولى في الدنيا، ثم نبقى ترابًا، وما نحن بمنشَرين، أي مبعوثين بعد الموتِ للحساب «إن هي إلا موتتنا الأولى وما نحن بمنشرين»؛ ففي هذا بيانُ إنكارِ المشركين للبعثِ والنشور؛ فزعموا أنه لا حياةَ بعد الموتِ ولا بعث؛ فاحذر إنكارَ النشورِ والبعثِ بعد الموت؛ فالله قادرٌ على إعادةِ الخلقِ كما بدأهم أوّلَ مرّة؛ كما بدأكم تعودون؛ قل يحييها الذي أنشأها أوّلَ مرّة؛ فالذي خلقك من عدمٍ قادرٌ على إعادتك بعد الموت؛ فأيقن بالنشورِ والبعثِ يقينًا جازمًا؛ واستعدّ له بالإيمانِ والعملِ الصالح؛ فإنكارُ النشورِ جهلٌ بقدرةِ الله وحكمته؛ فمن أنكره ضلّ وخسر، ومن أيقن به استعدّ وربح؛ فاجعل يقينك بالنشورِ راسخًا؛ واعمل لما بعد الموتِ من البعثِ والحساب؛ فالموتُ ليس نهايةً، بل بابٌ إلى الآخرةِ والجزاء."}},{"n":36,"reflection":{"text":"«فأتوا بآبائنا إن كنتم صادقين»: يقولون تعجيزًا: فأحيوا آباءنا الأموات إن كنتم صادقين في البعث؛ ففي هذا بيانُ عنادهم وتعجيزهم؛ فاحذر معارضةَ الحقِّ بالتعجيزِ والعناد، فطلبُ الآياتِ تعنّتًا من صفاتِ المكذّبين، فاقبل الحقَّ ببرهانه ولا تتعنّت.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"قبولُ الحقِّ ببرهانه، وتركُ التعنّتِ والتعجيز."},"action":{"text":"تأمّل عنادَ المشركين وتعجيزهم: يقول المشركون للنبيِّ والمؤمنين على سبيلِ التعجيزِ والعناد: فأتوا وأحيوا لنا آباءنا الذين ماتوا إن كنتم صادقين في دعوى البعثِ والنشور «فأتوا بآبائنا إن كنتم صادقين»؛ ففي هذا بيانُ عنادِ المشركين وتعجيزهم بطلبِ ما ليس إليهم؛ فطلبوا إحياءَ آبائهم في الدنيا دليلًا على البعث، وهذا تعنّتٌ وعناد؛ فليس البعثُ في الدنيا، بل يومَ القيامة؛ فاحذر معارضةَ الحقِّ بالتعجيزِ والعنادِ وطلبِ ما ليس من شأنه؛ فطلبُ الآياتِ تعنّتًا وعنادًا من صفاتِ المكذّبين المعاندين؛ وقالوا لن نؤمن لك حتى تفجّر لنا من الأرضِ ينبوعًا؛ فالمكذّبون يطلبون الآياتِ تعنّتًا لا استرشادًا؛ فاقبل أنت الحقَّ ببرهانه ودليله؛ ولا تتعنّت ولا تطلب ما ليس من شأنِ الحق؛ فمن طلب الحقَّ بصدقٍ اهتدى، ومن تعنّت وعاند ضلّ؛ فاجعل طلبك للحقِّ طلبَ استرشادٍ لا طلبَ تعجيزٍ وعناد."}},{"n":37,"reflection":{"text":"«أهم خير أم قوم تبع والذين من قبلهم أهلكناهم إنهم كانوا مجرمين»: أهؤلاء المشركون خيرٌ أم قومُ تبّعٍ ومن قبلهم؟ أهلكناهم لإجرامهم؛ ففي هذا التخويفُ بمصارعِ الأمم؛ فاعتبر بإهلاكِ الأممِ المجرمةِ التي كانت أقوى، فالإجرامُ سببُ الهلاك، فاحذر الإجرامَ لئلا يصيبك ما أصابهم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بمصارعِ الأممِ المجرمة، والحذرُ من الإجرام."},"action":{"text":"تأمّل التخويفَ بمصارعِ الأمم: أهؤلاء المشركون من قريشٍ خيرٌ وأقوى، أم قومُ تبّعٍ، ملوكِ اليمنِ وأتباعهم، والذين من قبلهم من الأممِ كعادٍ وثمود؟ أهلكناهم جميعًا بذنوبهم، إنهم كانوا مجرمين مكذّبين «أهم خير أم قوم تبع والذين من قبلهم أهلكناهم إنهم كانوا مجرمين»؛ ففي هذا التخويفُ لقريشٍ بمصارعِ الأممِ المجرمةِ التي كانت أقوى منهم؛ فقومُ تبّعٍ ومن قبلهم كانوا أكثرَ قوّةً وأموالًا، فأهلكهم الله بإجرامهم؛ فما يُؤمِّن قريشًا أن يصيبهم ما أصاب من قبلهم؟ فاعتبر بإهلاكِ الأممِ المجرمةِ التي كانت أعظمَ منك قوّةً وعددًا؛ فالإجرامُ والتكذيبُ سببُ الهلاكِ والعذاب؛ أفلم يسيروا في الأرضِ فينظروا كيف كان عاقبةُ الذين من قبلهم؛ كانوا أشدَّ منهم قوّةً؛ فاحذر الإجرامَ والتكذيبَ لئلا يصيبك ما أصاب المجرمين قبلك؛ فمن اتّعظ بمصارعِ الأممِ نجا، ومن غفل عنها هلك؛ فاجعل من قصصِ المهلَكين عبرةً تحملك على الإيمانِ والطاعةِ وتركِ الإجرام."}},{"n":38,"reflection":{"text":"«وما خلقنا السماوات والأرض وما بينهما لاعبين»، وما خلقنا السماواتِ والأرضَ وما بينهما لاهين عابثين؛ ففي هذا بيانُ أنّ الخلقَ لحكمة؛ فاعلم أنّ الله ما خلق الكونَ عبثًا، بل لحكمةٍ عظيمة، فتدبّر حكمةَ الخلق، واعمل لما خُلِقت له من عبادةِ الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تدبّرُ حكمةِ الخلق، والعملُ لما خُلِقنا له من عبادةِ الله."},"action":{"text":"تأمّل بيانَ أنّ الخلقَ لحكمة: وما خلقنا السماواتِ والأرضَ وما بينهما من المخلوقاتِ العظيمة لاعبين عابثين لاهين، بلا حكمةٍ ولا غاية «وما خلقنا السماوات والأرض وما بينهما لاعبين»؛ ففي هذا بيانُ أنّ الله لم يخلقِ الكونَ عبثًا ولا لعبًا؛ فتنزّه الله عن العبثِ في خلقه؛ فما خلق السماواتِ والأرضَ لهوًا ولعبًا؛ فاعلم أنّ الله ما خلق الكونَ عبثًا، بل لحكمةٍ عظيمةٍ وغايةٍ جليلة؛ أفحسبتم أنما خلقناكم عبثًا؛ لو أردنا أن نتّخذ لهوًا لاتّخذناه من لدنّا؛ فتدبّر حكمةَ الله في خلقِ الكونِ العظيم؛ فما خلقه إلا ليُعبَد ويُوحَّد، وليَبعث الخلقَ ويجزيهم؛ وما خلقتُ الجنَّ والإنسَ إلا ليعبدون؛ فاعمل لما خُلِقت له من عبادةِ الله وحده؛ فأنت لم تُخلَق عبثًا، بل لغايةٍ عظيمةٍ هي عبادةُ الله؛ فمن عرف حكمةَ خلقه فعبد الله فقد اهتدى، ومن غفل عنها فعاش لاهيًا فقد ضلّ؛ فاجعل حياتك عبادةً لله؛ فبها تحقّق الغايةَ من خلقك."},"qadiyya":{"title":"قضيّةُ نفيٍ يُثبت: لماذا نُفي اللعبُ قبل أن يُثبت الحقّ؟","question":"قال الله: «وما خلقنا السماوات والأرض وما بينهما لاعبين، ما خلقناهما إلّا بالحقّ ولكنّ أكثرهم لا يعلمون».\nفنُفي اللعبُ أوّلًا، ثمّ أُثبت الحقُّ ثانيًا.\n**ولو أُريد الإثباتُ وحده لكفى**: ما خلقناهما إلّا بالحقّ.\nفالقضيّة: **ما فائدةُ تقديم النفي؟** ثمّ: ما «الحقّ» الذي خُلقتا به؟ ثمّ: ما صلةُ ﴿ولكنّ أكثرهم لا يعلمون﴾ بما قبلها؟","background":"ولا يظهر موضعُ النفي حتى نعرف أنّ الناس في الغاية من الخلق على أقوال:\nفمنهم من يقول: لا غاية؛ وهو القولُ بالعبث.\nومنهم من يُثبت غايةً دنيويّة تنتهي بانتهاء الدنيا.\nومنهم من يُثبت غايةً تتجاوزها.\nوالآيةُ **نفت الأوّل وأثبتت الثالث**.\nفالنفيُ إذًا **ليس تكرارًا**؛ إنّه إبطالٌ لقولٍ قائم.","what_happened":"بيّن السعديُّ ما تضمّنه النفي: «يُخبر تعالى عن كمال قدرته وتمام حكمته، وأنّه ما خلق السماوات والأرض لعبًا ولا لهوًا أو سدًى من غير فائدة».\nفذكر **ثلاثة ألفاظٍ في النفي**: اللعبَ، واللهو، والسدى.\n⭐ ثمّ فسّر ﴿بالحقّ﴾ **بوجهين لا وجهٍ واحد**: «أي: نفسُ خلقهما بالحقّ، وخلقُهما مشتملٌ على الحقّ».\nفالحقُّ **في الفعل، والحقُّ فيما وقع به الفعل**.\n⭐ ثمّ بيّن الغاية بعد ذلك: «وأنّه أوجدهما ليعبدوه وحده لا شريك له، وليأمر العبادَ وينهاهم ويثيبهم ويعاقبهم».\n⭐ ثمّ ربط الختامَ بما قبله **ربطًا سببيًّا**: ﴿ولكنّ أكثرهم لا يعلمون﴾ «فلذلك لم يتفكّروا في خلق السماوات والأرض».","the_verdict":"فالحاصلُ أنّ الآية **أبطلت دعوى العبث ثمّ عيّنت البديل**.\n⭐ وأمّا الألفاظُ الثلاثة في النفي **فليست ترادفًا**:\n«لعبًا»: فعلٌ لغير غاية، فيه انشغال.\n«ولا لهوًا»: صرفٌ عن غيره.\n«أو سدًى من غير فائدة»: وهذا أعمُّها؛ أن يقع بلا ثمرة.\nفنُفيت الصور كلُّها، فلم يبقَ مدخلٌ لمن يقول: ليس لعبًا ولكن لا غاية له.\n⭐ وأمّا تفسيرُه ﴿بالحقّ﴾ بوجهين فدقيق.\nفالوجهُ الأوّل «نفسُ خلقهما بالحقّ»: أي أنّ الفعل نفسَه صدر عن حكمة، لا عن عبث.\nوالوجهُ الثاني «وخلقُهما مشتملٌ على الحقّ»: أي أنّ ما فيهما من نظامٍ وإتقانٍ حقٌّ في نفسه.\nف**الأوّلُ في جهة الفاعل، والثاني في جهة المفعول**.\n⭐ وأمّا الغايةُ فقد ذكرها في ثلاث: العبادةُ، والأمرُ والنهي، والجزاء.\nوترتيبُها لازم؛ فإنّ العبادة لا تكون بلا أمرٍ ونهي، والأمرُ والنهي لا يستقيمان بلا جزاء.\nفمن أنكر الجزاء عاد الأمرُ والنهي إلى ما يشبه العبث الذي نفته الآية.\n⭐ وأمّا ﴿ولكنّ أكثرهم لا يعلمون﴾ فقد جعله الإمامُ **سببًا لا نتيجة**: «فلذلك لم يتفكّروا».\nفليس المعنى أنّهم لم يتفكّروا فلم يعلموا؛ بل أنّهم **لمّا لم يعلموا لم يتفكّروا**.\nفالجهلُ يمنع من الطلب، لأنّ الطالب إنّما يطلب ما يعلم أنّ ثَمّ شيئًا يُطلب.\nفمن لم يخطر بباله أنّ للخلق غايةً لم يبحث عنها.","for_you":"فأمّا الذي تخرج به فثلاثة:\nالأوّل: إذا قرّرتَ حقًّا **فابدأ بنفي ضدّه**. فقد بُدئ في الآية بنفي اللعب قبل إثبات الحقّ. فمن أثبت ولم ينفِ ترك للمخالف مدخلًا؛ فإنّ السامع قد يُقرّ بما تقول وهو مُبقٍ على ما عنده.\nوالثاني: **استوفِ صور النفي**. فقد نُفي اللعبُ واللهوُ والسدى؛ ولو نُفي واحدٌ لبقي الباقي. وكذلك أنت إذا نفيتَ عن أمرٍ وصفًا فانظر في نظائره؛ فإنّ الخصم يخرج من الباب الذي تركتَه.\nوالثالث: اعلم أنّ **الجهل يمنع السؤال**. فقد جعل الإمامُ عدمَ العلم سببًا لترك التفكّر. فإن أردتَ أن تُحرّك أحدًا للنظر فلا تبدأ بالجواب؛ ابدأ بأن تُوقظ عنده السؤال. فمن لم يشعر أنّ ثَمّ ما يُطلب، لن يطلب.","grade":"ma'thur","source":"بيانُ السعديّ لما تضمّنه النفي («يخبر تعالى عن كمال قدرته وتمام حكمته وأنه ما خلق السماوات والأرض لعبا ولا لهوا أو سدى من غير فائدة»)، وتفسيرُه ﴿بالحق﴾ بوجهين («أي: نفس خلقهما بالحق وخلقهما مشتمل على الحق»)، وبيانُه للغاية («وأنه أوجدهما ليعبدوه وحده لا شريك له وليأمر العباد وينهاهم ويثيبهم ويعاقبهم»)، وربطُه للختام («فلذلك لم يتفكروا في خلق السماوات والأرض»): كلُّها بنصّها في تفسير السعديّ (٤٤:٣٨ و٤٤:٣٩).","honesty":"وممّا يجب أن يُقال:\nعرضُنا في التمهيد لأقوال الناس في الغاية، تمهيدٌ منّا لبيان موضع النفي؛ **وليس نصًّا لإمامٍ ها هنا**.\nوأمّا تفريقُنا بين الألفاظ الثلاثة في النفي، فتحريرٌ منّا؛ **وقد ساقها السعديُّ ولم يُفرّق بينها**، ومن رأى أنّا وسّعنا فليردّه.\nوأمّا قولُنا إنّ من أنكر الجزاء عاد الأمرُ والنهي إلى ما يشبه العبث، فاستنباطٌ منّا من ترتيب ما ذكره في الغاية.\nوأمّا قولُنا إنّ الجهل يمنع الطلب، فتحريرٌ منّا لمعنى قوله «فلذلك لم يتفكروا»."}},{"n":39,"reflection":{"text":"«ما خلقناهما إلا بالحق ولكن أكثرهم لا يعلمون»: ما خلقناهما إلا بالحقِّ (لحكمةٍ وبعثٍ وجزاء)، ولكنّ أكثرهم لا يعلمون؛ ففي هذا تقريرُ الحكمةِ من الخلق؛ فاعلم أنّ الله خلق الكونَ بالحق، فاطلب العلمَ بحكمةِ الله، فبالعلمِ تدرك الحقَّ والحكمة، فلا تكن من الجاهلين الغافلين.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ العلمِ بحكمةِ الله، وإدراكُ أنّ الخلقَ بالحق."},"action":{"text":"تأمّل تقريرَ الحكمةِ من الخلق: ما خلقنا السماواتِ والأرضَ إلا بالحقِّ، لحكمةٍ بالغةٍ وغايةٍ عظيمة: ليُعرَف الله ويُعبَد، ويُبعَث الخلقُ ويُجزَوا بأعمالهم؛ ولكنّ أكثرَ الناسِ لا يعلمون ذلك لغفلتهم وإعراضهم «ما خلقناهما إلا بالحق ولكن أكثرهم لا يعلمون»؛ ففي هذا تقريرُ أنّ الله خلق الكونَ بالحقِّ لا بالباطل، لحكمةٍ لا لعبث؛ فالخلقُ قائمٌ على الحقِّ والحكمة؛ ومن الحقِّ أن يُبعَث الخلقُ ويُجزَوا؛ ولكنّ أكثرَ الناسِ لا يعلمون هذه الحكمةَ لجهلهم وغفلتهم؛ يعلمون ظاهرًا من الحياةِ الدنيا وهم عن الآخرةِ هم غافلون؛ فاعلم أنت أنّ الله خلق الكونَ بالحقِّ والحكمة؛ واطلب العلمَ النافعَ الذي تدرك به حكمةَ الله وحقَّه؛ فبالعلمِ تدرك الحقَّ والحكمة، وتعرف الغايةَ من خلقك؛ ولا تكن من الجاهلين الغافلين الذين لا يعلمون؛ فمن علم الحقَّ وعمل به نجا، ومن جهله وأعرض عنه خسر؛ فاجعل من طلبِ العلمِ بحكمةِ الله وحقّه سبيلَك؛ فبالعلمِ والعملِ تحيا حياةً طيّبةً وتفوز بالآخرة."}}]},{"title":"يومُ الفصلِ ميقاتُ الجميع، ونجاةُ من رحمهم الله","range":[40,42],"theme":"تقريرُ يومِ الفصلِ ميقاتًا يجتمع فيه الخلقُ للجزاء، يومَ لا يُغني قريبٌ عن قريبٍ ولا يُنصَرون، إلا من رحمه الله فتنفعه رحمتُه، إنه هو العزيزُ الرحيم","verses":[{"n":40,"reflection":{"text":"«إن يوم الفصل ميقاتهم أجمعين»: إنّ يومَ الفصلِ (القضاءِ بين الخلق) ميقاتُ الجميعِ للحسابِ والجزاء؛ ففي هذا تقريرُ يومِ الفصل؛ فأيقن بيومِ الفصلِ الذي يُجمَع فيه الخلقُ للجزاء، واستعدّ له بالعمل، فيومُ الفصلِ ميقاتٌ لا يتخلّف عنه أحد، فبادر بالعملِ قبله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بيومِ الفصلِ والاستعدادُ له بالعمل."},"action":{"text":"تأمّل تقريرَ يومِ الفصل: إنّ يومَ الفصلِ، يومَ القيامةِ الذي يفصل الله فيه بين الخلقِ ويقضي بينهم بالحقّ، هو ميقاتُهم أجمعين، موعدُ اجتماعهم كلِّهم للحسابِ والجزاء «إن يوم الفصل ميقاتهم أجمعين»؛ ففي هذا تقريرُ يومِ الفصل، وأنه ميقاتٌ يجتمع فيه الأوّلون والآخرون؛ فيومَ الفصلِ يفصل الله فيه بين المحقِّ والمبطل، ويجزي كلًّا بعمله؛ إنّ يومَ الفصلِ كان ميقاتًا؛ هذا يومُ الفصلِ الذي كنتم به تكذّبون؛ فأيقن بيومِ الفصلِ الذي يُجمَع فيه الخلقُ كلُّهم للحسابِ والجزاء؛ واستعدّ له بالإيمانِ والعملِ الصالح؛ فيومُ الفصلِ ميقاتٌ محدّدٌ لا يتخلّف عنه أحد؛ ولا يظلم ربك أحدًا؛ فبادر بالعملِ الصالحِ قبل أن يأتيَ ذلك اليوم؛ فمن استعدّ له بالعملِ فاز، ومن غفل عنه خسر؛ فاجعل يقينك بيومِ الفصلِ حافزًا لك على العملِ والاستعداد؛ فإنه آتٍ لا محالة، ويجتمع فيه الخلقُ أجمعون للجزاء."}},{"n":41,"reflection":{"text":"«يوم لا يغني مولى عن مولى شيئا ولا هم ينصرون»: يومَ لا ينفع قريبٌ قريبَه، ولا يُنصَرون من عذابِ الله؛ ففي هذا بيانُ انقطاعِ الأسبابِ يومَ القيامة؛ فاعلم أنه لا ينفعك يومئذٍ إلا عملك، فاعمل لنفسك ولا تتّكل على أحد، فيومَ القيامةِ لا يُغني أحدٌ عن أحد، فقدّم لنفسك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ للنفسِ وعدمُ الاتّكالِ على أحد، فلا يُغني قريبٌ يومئذٍ."},"action":{"text":"تأمّل بيانَ انقطاعِ الأسبابِ يومَ القيامة: يومَ الفصلِ لا يُغني قريبٌ عن قريبه، ولا صديقٌ عن صديقه، ولا يدفع عنه شيئًا من عذابِ الله؛ ولا هم يُنصَرون من عذابِ الله بأحدٍ ينصرهم «يوم لا يغني مولى عن مولى شيئا ولا هم ينصرون»؛ ففي هذا بيانُ انقطاعِ الأسبابِ والأنسابِ والوسائطِ يومَ القيامة؛ فلا ينفع أحدٌ أحدًا، ولا يدفع عنه شيئًا؛ فلا أنسابَ بينهم يومئذٍ ولا يتساءلون؛ يومَ يفرُّ المرءُ من أخيه وأمّه وأبيه؛ فاعلم أنه لا ينفعك يومئذٍ إلا عملك الصالح؛ فاعمل لنفسك، ولا تتّكل على أحدٍ من قريبٍ أو صديقٍ أو جاه؛ فيومَ القيامةِ لا يُغني والدٌ عن ولده، ولا مولًى عن مولاه؛ واتّقوا يومًا لا تجزي نفسٌ عن نفسٍ شيئًا؛ فقدّم لنفسك عملًا صالحًا ينفعك يومئذٍ؛ فمن قدّم لنفسه نجا، ومن اتّكل على غيره خاب؛ فاجعل اعتمادك بعد الله على عملك الصالح؛ ولا تغترّ بقرابةٍ أو جاهٍ لا يُغني عنك شيئًا؛ فالنجاةُ يومئذٍ بالإيمانِ والعملِ الصالح."}},{"n":42,"reflection":{"text":"«إلا من رحم الله إنه هو العزيز الرحيم»: إلا من رحمه الله فينفعه، إنه هو العزيزُ الرحيم؛ ففي هذا استثناءُ أهلِ الرحمة؛ فاطلب رحمةَ الله التي تنفعك يومَ لا ينفع مالٌ ولا بنون، فبرحمةِ الله وحدها النجاة، فاعمل لتنال رحمته، وارجُ عزّته ورحمته.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ رحمةِ الله التي بها النجاة، والرجاءُ في عزّته ورحمته."},"action":{"text":"تأمّل استثناءَ أهلِ الرحمة: يومَ لا يُغني أحدٌ عن أحد، إلا من رحمه الله من المؤمنين، فينفعهم إيمانهم وعملهم، وتنالهم رحمةُ الله وشفاعةُ من أذن له؛ إنه هو العزيزُ الذي لا يُغالَب، الرحيمُ بعباده المؤمنين «إلا من رحم الله إنه هو العزيز الرحيم»؛ ففي هذا استثناءُ أهلِ الرحمةِ من المؤمنين الذين تنفعهم رحمةُ الله؛ فالنجاةُ يومئذٍ برحمةِ الله لا بالأنسابِ والأسباب؛ فمن رحمه الله نجا، ومن لم تدركه رحمته هلك؛ فاطلب رحمةَ الله التي تنفعك يومَ لا ينفع مالٌ ولا بنون؛ فبرحمةِ الله وحدها النجاةُ من عذابه؛ لن يدخل أحدًا منكم عمله الجنّة؛ قالوا ولا أنت يا رسول الله؟ قال ولا أنا، إلا أن يتغمّدني الله برحمة؛ فاعمل الصالحاتِ لتنال رحمةَ الله؛ وارجُ رحمته مع عملك؛ واجمع بين الخوفِ من عزّته والرجاءِ في رحمته؛ فهو العزيزُ الرحيم؛ فمن جمع بين العملِ ورجاءِ الرحمةِ فاز؛ فاجعل رجاءك في رحمةِ الله، وعملك سببًا لنيلها؛ فبرحمته تدخل الجنّةَ وتنجو من النار."}}]},{"title":"شجرةُ الزقّومِ طعامُ الأثيمِ وعذابُ الجحيم","range":[43,50],"theme":"وصفُ شجرةِ الزقّومِ طعامِ الأثيمِ تغلي في البطونِ كالمهلِ وكغليِ الحميم، وسوقِ الأثيمِ إلى سواءِ الجحيمِ وصبِّ الحميمِ فوق رأسه، والتهكّمِ به: ذق إنك أنت العزيزُ الكريم، إنّ هذا ما كنتم به تمترون","verses":[{"n":43,"reflection":{"text":"«إن شجرة الزقوم»: إنّ شجرةَ الزقّومِ (شجرةً خبيثةً في النار)؛ ففي هذا التخويفُ بطعامِ أهلِ النار؛ فاحذر عملَ أهلِ النارِ الذين طعامهم الزقّوم، فاعمل لتنجو منه، فالزقّومُ طعامُ الأثيمِ في النار، فاجتنب الآثامَ لتنجو من الزقّوم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من عملِ أهلِ النار، واجتنابُ الآثامِ للنجاةِ من الزقّوم."},"action":{"text":"تأمّل التخويفَ بطعامِ أهلِ النار: إنّ شجرةَ الزقّومِ، وهي شجرةٌ خبيثةٌ كريهةُ الطعمِ والرائحةِ تنبت في أصلِ الجحيم، أعدّها الله طعامًا لأهلِ النار «إن شجرة الزقوم»؛ ففي هذا التخويفُ بطعامِ أهلِ النارِ من شجرةِ الزقّومِ الخبيثة؛ فطعامُ أهلِ النارِ من هذه الشجرةِ الملعونة؛ إنها شجرةٌ تخرج في أصلِ الجحيم، طلعها كأنه رؤوسُ الشياطين؛ فاحذر عملَ أهلِ النارِ الذين يكون طعامهم الزقّوم؛ فاعمل عملًا صالحًا لتنجو من النارِ وطعامها؛ فالزقّومُ طعامُ الأثيمِ الكافرِ في النار؛ فاجتنب الآثامَ والكفرَ والمعاصي لتنجو من الزقّومِ والعذاب؛ فمن اجتنب الآثامَ وعمل صالحًا نجا من النارِ وطعامها، ومن أثم وكفر أُطعِم الزقّوم؛ فاجعل من ذكرِ الزقّومِ حافزًا لك على اجتنابِ الآثامِ والعملِ الصالح؛ فالنجاةُ من الزقّومِ بالإيمانِ والتقوى واجتنابِ الآثام."}},{"n":44,"reflection":{"text":"«طعام الأثيم»: هي طعامُ الأثيمِ (كثيرِ الآثامِ من الكفّار)؛ ففي هذا بيانُ أنّ الزقّومَ جزاءُ الآثام؛ فاحذر أن تكون من الأثيمين الذين طعامهم الزقّوم، فاجتنب الآثامَ وتب منها، فالإثمُ يورث عذابَ النار، فطهّر نفسك من الآثام.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اجتنابُ الآثامِ والتوبةُ منها، وتطهيرُ النفسِ منها."},"action":{"text":"تأمّل بيانَ أنّ الزقّومَ جزاءُ الآثام: شجرةُ الزقّومِ طعامُ الأثيمِ، وهو الكافرُ المصرُّ على الآثامِ والذنوبِ الكبار؛ يُطعَمها في النارِ جزاءَ إثمه وكفره «طعام الأثيم»؛ ففي هذا بيانُ أنّ الزقّومَ جزاءٌ للأثيمِ كثيرِ الآثام؛ فمن كثرت آثامه وكفره كان طعامه في النارِ الزقّوم؛ فاحذر أن تكون من الأثيمين الذين طعامهم الزقّوم؛ فاجتنب الآثامَ صغيرها وكبيرها؛ وتب إلى الله من كلِّ إثمٍ وذنب؛ فالإثمُ والإصرارُ عليه يورث عذابَ النارِ وطعامَ الزقّوم؛ وذروا ظاهرَ الإثمِ وباطنه؛ فطهّر نفسك من الآثامِ بالتوبةِ والاستغفارِ والعملِ الصالح؛ فمن طهّر نفسه من الآثامِ نجا من الزقّوم، ومن أصرّ عليها أُطعِمه؛ فاجعل همّك تطهيرَ نفسك من الآثام؛ فبالتوبةِ والعملِ الصالحِ تنجو من طعامِ الأثيم؛ فبادر بالتوبةِ من الآثامِ قبل فواتِ الأوان."}},{"n":45,"reflection":{"text":"«كالمهل يغلي في البطون»: الزقّومُ كعكرِ الزيتِ يغلي في البطونِ من شدّةِ حرارته؛ ففي هذا وصفُ شدّةِ عذابِ أهلِ النار؛ فاحذر هذا العذابَ الذي يغلي في البطون، فاعمل لتنجو منه، فعذابُ النارِ شديدٌ لا يُطاق، فاتّق النارَ بالإيمانِ والعمل.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من عذابِ النارِ الشديد، والعملُ للنجاةِ منه."},"action":{"text":"تأمّل وصفَ شدّةِ عذابِ الزقّوم: طعامُ الزقّومِ كالمهلِ، وهو عكرُ الزيتِ أو دُرديُّه، أو ما أُذيب من النحاسِ والمعادن، يغلي في البطونِ غليانًا شديدًا من فرطِ حرارته «كالمهل يغلي في البطون»؛ ففي هذا وصفُ شدّةِ حرارةِ الزقّومِ وغليانِه في بطونِ أهلِ النار؛ فإذا أكلوه غلى في بطونهم كغليِ الحميم؛ يُصهَر به ما في بطونهم والجلود؛ وإن يستغيثوا يُغاثوا بماءٍ كالمهلِ يشوي الوجوه؛ فاحذر هذا العذابَ الأليمَ الذي يغلي في البطون؛ فاعمل عملًا صالحًا لتنجو منه؛ فعذابُ النارِ شديدٌ لا يُطاق ولا يُحتمَل؛ نارُ الله الموقدةُ التي تطّلع على الأفئدة؛ فاتّق النارَ بالإيمانِ والعملِ الصالحِ والتقوى؛ ولو بشقِّ تمرة؛ فمن اتّقى النارَ بالعملِ الصالحِ نجا منها، ومن أهملها وقع فيها؛ فاجعل من تصوّرِ هذا العذابِ حافزًا لك على العملِ والتقوى؛ فالنجاةُ من النارِ بالإيمانِ والعملِ الصالحِ واجتنابِ المعاصي."}},{"n":46,"reflection":{"text":"«كغلي الحميم»: يغلي كغليِ الماءِ الحارِّ المتناهي في الحرارة؛ ففي هذا تأكيدُ شدّةِ العذاب؛ فاحذر عذابَ النارِ الذي يغلي كالحميم، فاعمل لتنجو منه، فشدّةُ العذابِ توجب الجدَّ في العمل، فاستعدّ للنجاة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الجدُّ في العملِ لشدّةِ العذاب، والاستعدادُ للنجاة."},"action":{"text":"تأمّل تأكيدَ شدّةِ عذابِ الزقّوم: يغلي الزقّومُ في بطونِ أهلِ النارِ كغليِ الحميمِ، وهو الماءُ الذي انتهى حرُّه وبلغ غايةَ الغليان «كغلي الحميم»؛ ففي هذا تأكيدُ شدّةِ حرارةِ الزقّومِ وغليانِه في البطون؛ فشبّه غليانه بغليانِ الحميمِ المتناهي في الحرارة؛ فهو يغلي في بطونهم كما يغلي الماءُ الحارُّ على النار؛ وسُقوا ماءً حميمًا فقطّع أمعاءهم؛ يُطاف بينها وبين حميمٍ آن؛ فاحذر هذا العذابَ الشديدَ الذي يغلي في البطونِ كالحميم؛ فاعمل عملًا صالحًا لتنجو منه؛ فشدّةُ هذا العذابِ توجب الجدَّ في العملِ والاستعدادِ للنجاة؛ فمن جدَّ في العملِ الصالحِ نجا، ومن تهاون وغفل وقع في العذاب؛ فاجعل من شدّةِ هذا العذابِ دافعًا لك على الجدِّ في الطاعةِ واجتنابِ المعاصي؛ فاستعدّ للنجاةِ من النارِ بالإيمانِ والتقوى والعملِ الصالح؛ فالنارُ لا يُنجي منها إلا الإيمانُ والعمل."}},{"n":47,"reflection":{"text":"«خذوه فاعتلوه إلى سواء الجحيم»: يُقال للزبانية: خذوا الأثيمَ فسوقوه بعنفٍ إلى وسطِ الجحيم؛ ففي هذا بيانُ إهانةِ أهلِ النار؛ فاحذر عملَ من يُساق إلى الجحيمِ بهذه الإهانة، فاعمل لتُكرَم لا لتُهان، فإهانةُ أهلِ النارِ جزاءُ كفرهم وطغيانهم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من عملِ أهلِ الإهانة، والعملُ لنيلِ الكرامة."},"action":{"text":"تأمّل بيانَ إهانةِ الأثيمِ في النار: يُقال لخزنةِ جهنّمَ عن الأثيمِ المتكبّر: خذوه بعنفٍ وشدّة، فاعتلوه، أي جرّوه وسوقوه بغلظةٍ وإهانة، إلى وسطِ الجحيمِ ومعظمِ نارها «خذوه فاعتلوه إلى سواء الجحيم»؛ ففي هذا بيانُ إهانةِ الأثيمِ المتكبّرِ وسوقِه إلى النارِ بعنف؛ فبعد أن كان في الدنيا متكبّرًا عزيزًا، يُساق في الآخرةِ إلى الجحيمِ ذليلًا مهانًا؛ يُدَعّون إلى نارِ جهنّمَ دعًّا؛ فاحذر عملَ من يُساق إلى الجحيمِ بهذه الإهانةِ والغلظة؛ فاعمل عملًا صالحًا لتُكرَم يومَ القيامةِ لا لتُهان؛ فإهانةُ أهلِ النارِ جزاءُ كفرهم وتكبّرهم وطغيانهم في الدنيا؛ فمن تكبّر في الدنيا أُهين في الآخرة، ومن تواضع لله أُكرِم؛ فاجعل عملك عملَ أهلِ الكرامة: من الإيمانِ والتواضعِ والطاعة؛ فمن أراد الكرامةَ يومَ القيامةِ فليعمل لها في الدنيا؛ فالكرامةُ بالتقوى، والإهانةُ بالكفرِ والطغيان."}},{"n":48,"reflection":{"text":"«ثم صبوا فوق رأسه من عذاب الحميم»: ثم صبّوا فوق رأسِه من الماءِ الحارِّ المُذيب عذابًا؛ ففي هذا زيادةُ عذابِ الأثيم؛ فاحذر هذا العذابَ الذي يُصَبُّ على الرؤوس، فاعمل لتنجو منه، فعذابُ الحميمِ فوق العذابِ، فاتّق الله لتنجو من عذاب النار.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من مضاعفةِ العذاب، والعملُ للنجاةِ منه."},"action":{"text":"تأمّل زيادةَ عذابِ الأثيمِ في النار: ثم صبّوا فوق رأسِ الأثيمِ من عذابِ الحميمِ، الماءِ الحارِّ الذي انتهى غليانه، يُصَبُّ على رأسه فينزل في جوفه ويُذيب ما فيه «ثم صبوا فوق رأسه من عذاب الحميم»؛ ففي هذا بيانُ مضاعفةِ عذابِ الأثيم: نارٌ من تحت، وحميمٌ يُصَبُّ من فوق؛ يُصهَر به ما في بطونهم والجلود؛ لهم من فوقهم ظللٌ من النارِ ومن تحتهم ظلل؛ فيُعذَّبون من كلِّ جهة؛ فاحذر هذا العذابَ المضاعفَ الذي يُصَبُّ على الرؤوس؛ فاعمل عملًا صالحًا لتنجو منه؛ فعذابُ الحميمِ فوق عذابِ النار، مضاعفةً للعقوبة؛ كلّما نضجت جلودهم بدّلناهم جلودًا غيرها؛ فاتّق الله بالإيمانِ والعملِ الصالحِ لتنجو من هذا العذاب؛ فمن اتّقى النارَ نجا من عذابها المضاعف، ومن أهملها وقع فيه؛ فاجعل من تصوّرِ هذا العذابِ دافعًا لك على التقوى والعملِ الصالح؛ فالنجاةُ من عذابِ النارِ المضاعفِ بالإيمانِ والتقوى."}},{"n":49,"reflection":{"text":"«ذق إنك أنت العزيز الكريم»: يُقال له تهكّمًا: ذق العذابَ، إنك أنت العزيزُ الكريمُ (كما كنت تزعم في الدنيا)؛ ففي هذا التهكّمُ بالمتكبّرين؛ فاحذر الكِبرَ والغرورَ في الدنيا لئلا تُهان في الآخرة، فتواضع لله، فالعزّةُ الحقّةُ بالتقوى لا بالكبر.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التواضعُ لله وتركُ الكِبر، فالعزّةُ الحقّةُ بالتقوى."},"action":{"text":"تأمّل التهكّمَ بالأثيمِ المتكبّر: يُقال للأثيمِ وهو يُعذَّب على سبيلِ التوبيخِ والتهكّم: ذق هذا العذابَ الأليم، إنك أنت، بزعمك في الدنيا، العزيزُ الذي لا يُضام، الكريمُ على قومك؛ فأين عزّتك وكرامتك الآن؟ «ذق إنك أنت العزيز الكريم»؛ ففي هذا التهكّمُ والتوبيخُ للمتكبّرين الذين ادّعوا العزّةَ والكرامةَ في الدنيا بالباطل؛ فقد كان أبو جهلٍ أو أمثالُه يزعم العزّةَ والكرامة، فيُقال له في النارِ تهكّمًا: ذق، إنك أنت العزيزُ الكريم؛ فاحذر الكِبرَ والغرورَ وادّعاءَ العزّةِ بالباطلِ في الدنيا لئلا تُهان وتُوبَّخ في الآخرة؛ فمن تكبّر في الدنيا أُهين وسُخِر منه في الآخرة؛ فتواضع لله وللخلق؛ ولا تدّعِ عزّةً ولا كرامةً بالباطل؛ فالعزّةُ الحقّةُ بالإيمانِ والتقوى والطاعة، لا بالكِبرِ والمالِ والجاه؛ من كان يريد العزّةَ فلله العزّةُ جميعًا؛ ولله العزّةُ ولرسوله وللمؤمنين؛ فاطلب العزّةَ من طاعةِ الله، لا من الكِبرِ والدنيا؛ فمن تواضع لله رفعه وأعزّه، ومن تكبّر أذلّه وأهانه."}},{"n":50,"reflection":{"text":"«إن هذا ما كنتم به تمترون»: إنّ هذا العذابَ هو ما كنتم به تشكّون وتكذّبون في الدنيا؛ ففي هذا تقريعُ المكذّبين؛ فاحذر الشكَّ والتكذيبَ بعذابِ الله، فأيقن بوعيدِ الله واعمل له، فالتكذيبُ بالعذابِ لا يدفعه، فأيقن به لتحذره.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بوعيدِ الله والعملُ له، وتركُ الشكِّ والتكذيب."},"action":{"text":"تأمّل تقريعَ المكذّبين: يُقال لأهلِ النارِ توبيخًا وتقريعًا: إنّ هذا العذابَ الذي أنتم فيه هو ما كنتم به في الدنيا تمترون، أي تشكّون وتكذّبون وتجادلون فيه «إن هذا ما كنتم به تمترون»؛ ففي هذا تقريعٌ للمكذّبين الذين كانوا يشكّون في عذابِ الله ويكذّبون به؛ فلمّا وقعوا فيه قيل لهم: هذا ما كنتم تشكّون فيه وتكذّبون؛ هذه النارُ التي كنتم بها تكذّبون؛ فاحذر أنت الشكَّ والتكذيبَ بعذابِ الله ووعيده؛ فأيقن بوعيدِ الله وعذابه يقينًا جازمًا؛ واعمل لذلك اليومِ عملًا ينجّيك من العذاب؛ فالتكذيبُ بالعذابِ والشكُّ فيه لا يدفعه ولا يمنعه؛ بل يقع بالمكذّبين لا محالة؛ فأيقن بالعذابِ لتحذره وتعمل للنجاةِ منه؛ فمن أيقن بوعيدِ الله عمل له ونجا، ومن شكّ فيه وكذّب به وقع فيه؛ فاجعل يقينك بوعيدِ الله حافزًا لك على العملِ والتقوى؛ فبادر بالتوبةِ والعملِ الصالحِ قبل أن يقع بك ما كنت تكذّب به."}}]},{"title":"نعيمُ المتّقين في مقامٍ أمينٍ وجنّاتٍ وحورٍ عين","range":[51,57],"theme":"جزاءُ المتّقين في مقامٍ أمينٍ وجنّاتٍ وعيون، يلبسون السندسَ والإستبرقَ متقابلين، وزُوّجوا بحورٍ عين، يدعون بكلِّ فاكهةٍ آمنين، لا يذوقون الموتَ ووقاهم عذابَ الجحيم فضلًا من ربّهم، ذلك هو الفوزُ العظيم","verses":[{"n":51,"reflection":{"text":"«إن المتقين في مقام أمين»: إنّ المتّقين في مقامٍ أمينٍ من كلِّ آفةٍ وخوف؛ ففي هذا بيانُ جزاءِ المتّقين؛ فاطلب هذا المقامَ الأمينَ بالتقوى، فالتقوى سبيلُ الأمنِ والنعيم، فاتّق الله لتنال المقامَ الأمينَ في الجنّة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ المقامِ الأمينِ بالتقوى، والحرصُ على التقوى."},"action":{"text":"تأمّل بيانَ جزاءِ المتّقين: إنّ المتّقين الذين اتّقوا الله بفعلِ أوامره واجتنابِ نواهيه، في الآخرةِ في مقامٍ أمينٍ، منزلٍ حسنٍ آمنٍ من كلِّ آفةٍ ومكروهٍ وخوفٍ وموت «إن المتقين في مقام أمين»؛ ففي هذا بيانُ جزاءِ المتّقين في الجنّة: مقامٌ أمينٌ آمن؛ فبعد أن ذكر عذابَ الأثيمِ في النار، ذكر نعيمَ المتّقين في الجنّة، ترغيبًا بعد ترهيب؛ فالمتّقون في مقامٍ أمينٍ من الموتِ والآفاتِ والأحزانِ والخوف؛ ادخلوها بسلامٍ آمنين؛ لا يمسّهم فيها نصبٌ وما هم منها بمخرَجين؛ فاطلب هذا المقامَ الأمينَ في الجنّةِ بالتقوى؛ فالتقوى، فعلُ المأموراتِ وتركُ المحظورات، سبيلُ الأمنِ والنعيمِ في الآخرة؛ وأزلفتِ الجنّةُ للمتّقين؛ إنّ المتّقين في جنّاتٍ ونهر، في مقعدِ صدقٍ عند مليكٍ مقتدر؛ فاتّق الله في السرِّ والعلن؛ وافعل ما أمرك به واجتنب ما نهاك عنه؛ فبالتقوى تنال المقامَ الأمينَ والنعيمَ المقيمَ في الجنّة؛ فمن اتّقى الله فاز بالجنّةِ ونعيمها، ومن فرّط خسر؛ فاجعل التقوى شعارك ودثارك؛ فهي مفتاحُ المقامِ الأمين."}},{"n":52,"reflection":{"text":"«في جنات وعيون»: هم في بساتينَ وأنهارٍ جارية؛ ففي هذا وصفُ نعيمِ المتّقين؛ فاطلب هذه الجنّاتِ والعيونَ بالتقوى والعمل، فنعيمُ الجنّةِ لا يفنى، فاعمل لتنال جنّاتِ النعيم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ جنّاتِ النعيمِ بالتقوى والعمل."},"action":{"text":"تأمّل وصفَ نعيمِ المتّقين: المتّقون في الجنّةِ في جنّاتٍ وبساتينَ عظيمةٍ جامعةٍ لأصنافِ الأشجارِ والثمار، وعيونٍ وأنهارٍ جاريةٍ متدفّقةٍ يفجّرونها كيف شاؤوا «في جنات وعيون»؛ ففي هذا وصفُ نعيمِ المتّقين في الجنّة: جنّاتٌ وعيون؛ فهم في بساتينَ من كلِّ ثمرٍ ونعيم، وعيونٍ جاريةٍ من الماءِ واللبنِ والخمرِ والعسل؛ مثلُ الجنّةِ التي وُعِد المتّقون فيها أنهارٌ من ماءٍ غيرِ آسن؛ إنّ المتّقين في جنّاتٍ وعيون؛ فاطلب هذه الجنّاتِ والعيونَ بالتقوى والإيمانِ والعملِ الصالح؛ فنعيمُ الجنّةِ دائمٌ لا يفنى ولا ينقطع؛ أُكُلها دائمٌ وظلّها؛ عطاءً غيرَ مجذوذ؛ فاعمل لتنال جنّاتِ النعيمِ وعيونها؛ فمن اتّقى الله وعمل صالحًا نالها، ومن فرّط حُرِمها؛ فاجعل همّك العملَ لجنّاتِ النعيم؛ فسارعوا إلى مغفرةٍ من ربّكم وجنّةٍ عرضها السماواتُ والأرضُ أُعِدّت للمتّقين؛ فسابق إليها بالعملِ الصالح."}},{"n":53,"reflection":{"text":"«يلبسون من سندس وإستبرق متقابلين»: يلبسون من رقيقِ الحريرِ وغليظِه، متقابلين في مجالسهم؛ ففي هذا وصفُ لباسِ أهلِ الجنّةِ وأنسهم؛ فاطلب هذا النعيمَ بالعملِ الصالح، فأهلُ الجنّةِ في لباسٍ ونعيمٍ وأنس، فاعمل لتكون منهم متقابلين على سررٍ متحابّين.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لنعيمِ الجنّةِ ولباسها، وطلبُ صحبةِ الصالحين فيها."},"action":{"text":"تأمّل وصفَ لباسِ أهلِ الجنّةِ وأنسهم: يلبس المتّقون في الجنّةِ من سندسٍ، وهو رقيقُ الحريرِ وناعمه، وإستبرقٍ، وهو غليظُ الحريرِ وثخينه، حالَ كونهم متقابلين في مجالسهم، ينظر بعضهم إلى بعضٍ متحابّين متآنسين «يلبسون من سندس وإستبرق متقابلين»؛ ففي هذا وصفُ لباسِ أهلِ الجنّةِ من الحريرِ الرقيقِ والغليظ، وأنسِهم بتقابلهم؛ فلباسهم الحريرُ الذي حُرِّم عليهم في الدنيا؛ وحُلّوا أساورَ من فضّةٍ؛ عاليهم ثيابُ سندسٍ خضرٌ وإستبرق؛ ومجالسهم أنسٌ ومحبّةٌ، متقابلين على سررٍ لا يرى بعضهم قفا بعض؛ ونزعنا ما في صدورهم من غلٍّ إخوانًا على سررٍ متقابلين؛ فاطلب هذا النعيمَ، اللباسَ والأنسَ والصحبةَ الطيّبة، بالعملِ الصالح؛ فأهلُ الجنّةِ في لباسٍ فاخرٍ ونعيمٍ وأنسٍ ومحبّة؛ فاعمل لتكون منهم متقابلين متحابّين؛ واطلب في الدنيا صحبةَ الصالحين لتكون معهم في الآخرة؛ المرءُ مع من أحبّ؛ فمن أحبّ الصالحين وعمل بعملهم كان معهم؛ فاجعل عملك عملَ أهلِ الجنّة، وصحبتك صحبةَ أهلِ الخير؛ فبالعملِ الصالحِ وصحبةِ الأخيارِ تنال نعيمَ الجنّةِ وأنسها."}},{"n":54,"reflection":{"text":"«كذلك وزوجناهم بحور عين»: كذلك يكون نعيمهم، وزوّجناهم بحورٍ عينٍ (نساءٍ بيضٍ واسعاتِ العيونِ حسان)؛ ففي هذا تمامُ نعيمِ الجنّة؛ فاطلب هذا النعيمَ بالعملِ الصالح، فنعيمُ الجنّةِ كاملٌ لا نقص فيه، فاعمل لتنال أزواجَ الجنّةِ الطاهرات.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لنعيمِ الجنّةِ الكامل، وطلبُ أزواجها الطاهرات."},"action":{"text":"تأمّل تمامَ نعيمِ أهلِ الجنّة: كذلك يكون إكرامنا للمتّقين، وزوّجناهم، قرنّاهم، بحورٍ عينٍ: نساءٍ بيضٍ حسانٍ واسعاتِ العيونِ جميلاتها، طاهراتٍ كاملاتِ الخَلقِ والخُلُق «كذلك وزوجناهم بحور عين»؛ ففي هذا تمامُ نعيمِ أهلِ الجنّةِ بتزويجهم الحورَ العين؛ فمع الجنّاتِ والعيونِ واللباسِ والأنس، زوّجهم الله الحورَ العينَ الطاهرات؛ فيهنّ خيراتٌ حسان، حورٌ مقصوراتٌ في الخيام؛ كأنهنّ الياقوتُ والمرجان؛ عُربًا أترابًا؛ فاطلب هذا النعيمَ الكاملَ بالعملِ الصالحِ والتقوى؛ فنعيمُ الجنّةِ كاملٌ لا نقصَ فيه ولا كدر؛ فيها ما تشتهيه الأنفسُ وتلذُّ الأعين؛ فاعمل لتنال أزواجَ الجنّةِ الطاهراتِ ونعيمها الكامل؛ فمن عمل صالحًا وهو مؤمنٌ فأولئك يدخلون الجنّةَ يُرزَقون فيها بغيرِ حساب؛ فاجعل عملك خالصًا صالحًا لتنال نعيمَ الجنّةِ الكامل؛ فالجنّةُ دارُ النعيمِ الكاملِ الذي لا ينقطع، أعدّها الله لعباده المتّقين."}},{"n":55,"reflection":{"text":"«يدعون فيها بكل فاكهة آمنين»: يطلبون في الجنّةِ كلَّ ما يشتهون من الفاكهةِ آمنين من كلِّ مكروه؛ ففي هذا كمالُ نعيمِ الجنّةِ ولذّته وأمنه؛ فاطلب هذا النعيمَ بالعملِ الصالح، فأهلُ الجنّةِ في لذّةٍ وأمنٍ دائم، فاعمل لتنال لذّةَ الجنّةِ وأمنها.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لنعيمِ الجنّةِ ولذّتها وأمنها الدائم."},"action":{"text":"تأمّل كمالَ نعيمِ أهلِ الجنّة: يدعو أهلُ الجنّةِ ويطلبون خدَمهم أن يأتوهم بكلِّ ما يشتهون ويتمنّون من أنواعِ الفاكهةِ اللذيذة، حالَ كونهم آمنين من كلِّ مكروهٍ: من انقطاعِ النعيم، أو المرض، أو الموت، أو الأذى «يدعون فيها بكل فاكهة آمنين»؛ ففي هذا كمالُ نعيمِ الجنّة: لذّةٌ في المطعمِ وأمنٌ من الزوال؛ فيدعون بكلِّ فاكهةٍ يشتهونها فتُحضَر لهم؛ وفاكهةٍ ممّا يتخيّرون؛ وفاكهةٍ كثيرة، لا مقطوعةٍ ولا ممنوعة؛ آمنين لا يخافون فواتها ولا مرضًا ولا موتًا؛ لا يذوقون فيها الموتَ إلا الموتةَ الأولى؛ فاطلب هذا النعيمَ الكاملَ اللذيذَ الآمنَ بالعملِ الصالحِ والتقوى؛ فأهلُ الجنّةِ في لذّةٍ دائمةٍ وأمنٍ لا يزول؛ ولهم فيها ما يدّعون؛ لهم ما يشاؤون فيها؛ فاعمل لتنال لذّةَ الجنّةِ وأمنها؛ فمن عمل للجنّةِ نالها، ومن غفل عنها حُرِمها؛ فاجعل همّك العملَ لدارِ اللذّةِ والأمن؛ فالجنّةُ دارٌ لا خوفَ فيها ولا حزنَ ولا نقص؛ نعيمٌ كاملٌ دائمٌ آمن؛ فاسعَ إليها بالعملِ الصالح."}},{"n":56,"reflection":{"text":"«لا يذوقون فيها الموت إلا الموتة الأولى ووقاهم عذاب الجحيم»: لا يذوقون في الجنّةِ موتًا إلا الموتةَ الأولى في الدنيا، ووقاهم الله عذابَ الجحيم؛ ففي هذا بيانُ خلودِ نعيمِ الجنّةِ ونجاتهم من النار؛ فاطلب هذا الخلودَ والنجاةَ بالتقوى، فنعيمُ الجنّةِ خالدٌ لا موتَ فيه، فاعمل لتخلد فيها وتنجو من النار.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ للخلودِ في الجنّةِ والنجاةِ من النار."},"action":{"text":"تأمّل بيانَ خلودِ نعيمِ الجنّة: لا يذوق أهلُ الجنّةِ فيها الموتَ أبدًا، إلا الموتةَ الأولى التي ذاقوها في الدنيا، فلا موتَ بعدها؛ ووقاهم الله برحمتِه عذابَ الجحيمِ ونجّاهم منه «لا يذوقون فيها الموت إلا الموتة الأولى ووقاهم عذاب الجحيم»؛ ففي هذا بيانُ خلودِ أهلِ الجنّةِ في النعيمِ بلا موت، ونجاتهم من عذابِ النار؛ فنعيمهم دائمٌ لا ينقطع بموت؛ يُؤتى بالموتِ يومَ القيامةِ كبشًا أملحَ فيُذبَح، ويُقال: يا أهلَ الجنّةِ خلودٌ فلا موت؛ فيزدادون فرحًا إلى فرحهم؛ خالدين فيها لا يبغون عنها حِوَلًا؛ ووقاهم الله عذابَ الجحيمِ فضلًا منه ورحمة؛ فاطلب هذا الخلودَ في النعيمِ والنجاةَ من النارِ بالتقوى والعملِ الصالح؛ فنعيمُ الجنّةِ خالدٌ لا موتَ فيه ولا انقطاع؛ فاعمل لتخلد في الجنّةِ وتنجو من النار؛ فمن اتّقى الله ووقاه عذابَ الجحيمِ فقد فاز؛ فمن زُحزِح عن النارِ وأُدخِل الجنّةَ فقد فاز؛ فاجعل غايتك الخلودَ في الجنّةِ والنجاةَ من النار؛ فبالإيمانِ والتقوى والعملِ الصالحِ تنالهما."},"qadiyya":{"title":"قضيّةُ استثناءٍ يدلّ على النفي","question":"قال الله في وصف أهل الجنّة: ﴿لا يذوقون فيها الموت إلّا الموتة الأولى﴾.\nوظاهرُ الاستثناء **إخراجُ شيءٍ ممّا دخل في الحكم**؛ فيوهم أنّ ثمّ موتةً في الجنّة استُثنيت من النفي. والموتةُ الأولى إنّما وقعت في الدنيا قبل دخول الدار.\nفالقضيّة: كيف يصحّ أن يُستثنى من الموت في الجنّة موتةٌ لم تقع فيها؟ ثمّ: كيف صار الاستثناءُ **حجّةً على نفي الموت** لا على إثباته؟ ثمّ: ما الذي يترتّب على انتفاء الموت في تمام النعيم؟","background":"ولا يظهر وجهُ الحجّة حتى يُفرّق بين اللفظ وموضعه من التركيب:\nفاللفظُ يدلّ بمعناه، و**موضعُه يدلّ بما اقتضاه وقوعُه حيث وقع**.\nوفي الاستثناء أصلٌ عامّ: أنّ المتكلّم إنّما يُخرج من الحكم ما كان داخلًا فيه.\nفإذا كان في محلّ الحكم شيءٌ يصحّ إخراجُه، كان **هو الأولى بالإخراج** من غيره.\nوالظرفُ في ﴿فيها﴾ قيّد نفي الذوق بالجنّة؛ فمحلُّ الحكم هو الدار وحدها.\nوالموتةُ الأولى خارجةٌ عن هذا المحلّ؛ إذ هي موتةُ الدنيا.","what_happened":"جرى السعديُّ في هذه الآيات على وصف تمام النعيم.\nفقال في تفسير قوله ﴿في جنّات وعيون﴾: «فأضاف الجنات إلى النعيم لأن كل ما اشتملت عليه كله نعيم وسرور»، ثمّ وصف ذلك بأنّه «كامل من كل وجه ما فيه منغص ولا مكدر بوجه من الوجوه».\nوقال عند ﴿كذلك﴾: «النعيم التام والسرور الكامل».\nثمّ عدّ في ﴿آمنين﴾ وجوهَ أمنهم، وختمها بقوله: «وآمنين من الخروج منها والموت».\n⭐ ثمّ جاء إلى الاستثناء فقرّر مقتضاه أوّلًا: «أي: ليس فيها موت بالكلية».\nثمّ **أخذ الدليل من موضع المستثنى** لا من ظاهر اللفظ، فقال: «ولو كان فيها موت يستثنى لم يستثن الموتة الأولى التي هي الموتة في الدنيا».\nثمّ رتّب على ذلك ثمرتَه: «فتم لهم كل محبوب مطلوب».\n⭐ ثمّ قال في ﴿فضلًا من ربّك﴾: «حصول النعيم واندفاع العذاب عنهم من فضل الله عليهم وكرمه»، ثمّ ساق تعليله: «فإنه تعالى هو الذي وفقهم للأعمال الصالحة التي بها نالوا خير الآخرة وأعطاهم أيضا ما لم تبلغه أعمالهم».","the_verdict":"فالحاصلُ أنّ الاستثناء ها هنا **دليلُ نفيٍ لا دليلُ إثبات**.\nوأمّا صحّتُه مع أنّ الموتة الأولى لم تقع في الدار، فمن جهة أنّ المستثنى واقعٌ خارج الظرف الذي عُلّق به الحكم؛ فلم يُخرَج من الدار شيءٌ كان فيها.\nولو كان في الدار موتةٌ لكانت هي المستثناة. فصار **العدولُ عن الأقرب إلى الأبعد** بيانًا لخلوّ الأقرب ممّا يُستثنى.\nوموضعُ الغلط عند من لم ينتبه أمران:\nالأوّل: أن يجعل الاستثناء إثباتًا لموتةٍ في الجنّة، فيقرأ الآية على ضدّ ما سيقت له.\nوالثاني: أن يجعله فضلًا من الكلام لا فائدة تحته؛ وهو أشدُّ، لأنّ الفائدة فيه أنّ النفي بلغ مبلغًا لم يبقَ معه ما يصلح للاستثناء إلّا ما هو خارجُ الدار أصلًا.\n⭐ وأمّا ثمرةُ ذلك ففي قوله «فتم لهم كل محبوب مطلوب»؛ وموضعُ النظر لفظُ التمام.\nفالنعيمُ الذي يُنتظر انقطاعُه ناقصٌ وإن عظُم؛ إذ توقّعُ زواله داخلٌ في حال صاحبه. فلمّا انتفى الموت بالكلّيّة ارتفع المنغّص الذي به يُنقص النعيم.\nوهذا يجري مع سائر ما قرّره: أمنُهم من الموت عند ﴿آمنين﴾، ونفيُ المنغّص عند ﴿في جنّات وعيون﴾، ووصفُ النعيم بالتمام عند ﴿كذلك﴾؛ فجاء الاستثناءُ مقرّرًا لها لا ناقضًا.\n⭐ ثمّ ردّ ذلك كلَّه إلى الفضل والكرم؛ فالتوفيقُ للعمل منه، والزيادةُ على ما بلغته الأعمال منه.","for_you":"فأمّا الذي تخرج به فثلاثة:\nالأوّل: **قف على المستثنى قبل حكمك على الجملة.** فإذا مرّ بك استثناءٌ في آيةٍ فاسأل: أوقع المستثنى في محلّ الحكم أم خارجه؟ فإن كان خارجًا فانظر ماذا بقي في الداخل. اختبر ذلك اليوم في آيةٍ واحدةٍ تقرؤها، واكتب جوابك في سطر.\nوالثاني: **ميّز في احتجاجك بين اللفظ وموضعه.** فإذا نازعتَ في معنًى فاكتب سطرين: ما دلّ عليه اللفظ، وما دلّ عليه وقوعُ الكلمة حيث وقعت. ثمّ انظر أيّهما بنيتَ عليه قولك؛ فإنّ أكثر الغلط من الخلط بينهما.\nوالثالث: **حاسب نعمك بالدوام لا بالمقدار.** اكتب ثلاثًا ممّا تعدّه اليوم نعمةً، ثمّ اكتب بإزاء كلّ واحدةٍ متى تنقطع. ثمّ قِس المنقطع بالباقي، وانظر أين تصرف عنايتك.","grade":"ma'thur","source":"تفسيرُ السعديّ لنفي الموت («أي: ليس فيها موت بالكلية...»)، وحجّتُه من موضع الاستثناء («ولو كان فيها موت يستثنى...»)، وثمرتُها («فتم لهم كل محبوب مطلوب»)، ووصفُه الجنّات بالنعيم («فأضاف الجنات إلى النعيم...») وكمالَها («كامل من كل وجه...»)، وقولُه عند ﴿كذلك﴾ («النعيم التام...»)، وما قدّمه في ﴿آمنين﴾ من الأمن من الموت («وآمنين من الخروج منها...»)، وتفسيرُه ﴿فضلًا من ربّك﴾ («حصول النعيم واندفاع العذاب...») مع تعليله («فإنه تعالى هو الذي وفقهم...»): كلُّها بنصّها في تفسير السعديّ (٤٤:٥٢ إلى ٤٤:٥٧).","honesty":"وممّا يجب أن يُقال:\nالتفريقُ في التمهيد بين اللفظ وموضعه من التركيب تمهيدٌ منّا، لا نصَّ للسعديّ.\nوتقريرُ الأصل العامّ في الاستثناء، وأنّ ما في محلّ الحكم أولى بالإخراج، تقريرٌ منّا لأصلٍ لغويّ؛ والإمامُ لم يذكر الأصل، وإنّما جرى عليه في حجّته.\nوتسميتُنا صنيعَه أخذًا للدليل من موضع المستثنى، ووصفُنا إيّاه بالعدول عن الأقرب إلى الأبعد، عبارتان منّا على معنى كلامه.\nوقولُنا إنّ المستثنى واقعٌ خارج الظرف المعلَّق به الحكم تخريجٌ منّا لوجه صحّة الاستثناء.\nوقولُنا إنّ فائدة الاستثناء بلوغُ النفي مبلغًا لا يبقى معه ما يُستثنى، استنباطٌ منّا.\nوقولُنا إنّ النعيم المنتظر انقطاعُه ناقص، وإنّ توقّع الزوال داخلٌ في حال صاحبه، استنباطٌ منّا من لفظ التمام في كلامه.\nوقولُنا إنّه جرى على وصف تمام النعيم، وإنّ كلامه في هذه الآيات يجري بعضُه مع بعض، وصفٌ منّا لصنيعه.\nوموضعا الغلط اللذان ذكرناهما تقديرٌ منّا لما قد يقع للقارئ، ولم يذكرهما الإمام.\nوالثلاثةُ التي في آخر القضيّة تطبيقٌ منّا لا نقلٌ عنه؛ وقياسُ المنقطع بالباقي فيها جارٍ على ما قرّرناه نحن، والإمامُ إنّما قال بالتمام في نعيم الجنّة. ومن رأى أنّا وسّعنا فليردّه."}},{"n":57,"reflection":{"text":"«فضلا من ربك ذلك هو الفوز العظيم»: كان ذلك النعيمُ فضلًا من ربّك ونعمةً، ذلك هو الفوزُ العظيم؛ ففي هذا بيانُ أنّ النعيمَ فضلٌ من الله، وأنّ الجنّةَ هي الفوزُ العظيم؛ فاطلب هذا الفوزَ العظيمَ بالعمل، مع إدراكِ أنه فضلٌ من الله، فاشكر فضلَ الله واعمل لفوزه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ الفوزِ العظيمِ بالعمل، وشكرُ فضلِ الله مع الإخلاص."},"action":{"text":"تأمّل بيانَ أنّ النعيمَ فضلٌ من الله: كان ذلك النعيمُ العظيمُ للمتّقين فضلًا من ربّك ونعمةً وإحسانًا منه، لا بمجرّدِ أعمالهم؛ ذلك النعيمُ والنجاةُ من النارِ هو الفوزُ العظيمُ الذي لا فوزَ بعده «فضلا من ربك ذلك هو الفوز العظيم»؛ ففي هذا بيانُ أنّ نعيمَ الجنّةِ فضلٌ من الله ورحمة، وأنّ الجنّةَ والنجاةَ من النارِ هي الفوزُ الحقيقيُّ العظيم؛ فدخولُ الجنّةِ برحمةِ الله وفضله، والعملُ سببٌ لا موجِبٌ بذاته؛ لن يُدخِل أحدَكم عمله الجنّة، إلا أن يتغمّده الله برحمةٍ منه وفضل؛ فاطلب هذا الفوزَ العظيمَ، الجنّةَ والنجاةَ من النار، بالإيمانِ والعملِ الصالح؛ مع إدراكِ أنه فضلٌ من الله ورحمة؛ فاشكر فضلَ الله ونعمته، ولا تُعجَب بعملك؛ فمن زُحزِح عن النارِ وأُدخِل الجنّةَ فقد فاز، وما الحياةُ الدنيا إلا متاعُ الغرور؛ فاجعل غايتك الفوزَ العظيمَ بالجنّة؛ واعمل له مع الإخلاصِ ورجاءِ فضلِ الله؛ فمن جمع بين العملِ ورجاءِ فضلِ الله فاز الفوزَ العظيم؛ فاسعَ للفوزِ العظيمِ بالعملِ الصالحِ وشكرِ فضلِ الله."}}]},{"title":"تيسيرُ القرآنِ للتذكّر، والأمرُ بالارتقاب","range":[58,59],"theme":"بيانُ أنّ الله يسّر القرآنَ بلسانِ النبيِّ العربيِّ لعلّهم يتذكّرون، وأمرُ النبيِّ بالارتقابِ والصبرِ فإنهم مرتقبون، والعاقبةُ للمتّقين","verses":[{"n":58,"reflection":{"text":"«فإنما يسرناه بلسانك لعلهم يتذكرون»: فإنما يسّرنا القرآنَ بلغتِك العربيةِ لعلّهم يتذكّرون ويتّعظون؛ ففي هذا بيانُ تيسيرِ القرآنِ للتذكّر؛ فاعلم أنّ الله يسّر القرآنَ لتتذكّر به وتتّعظ، فتدبّره واتّعظ بمواعظه، فالقرآنُ ميسَّرٌ للذكرى، فأقبل عليه متذكّرًا.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تدبّرُ القرآنِ والاتّعاظُ به، وإدراكُ أنه ميسَّرٌ للذكرى."},"action":{"text":"تأمّل بيانَ تيسيرِ القرآنِ للتذكّر: فإنما يسّرنا هذا القرآنَ وسهّلناه بلسانك العربيِّ المبين، يا محمدُ، لتبلّغه لقومك، لعلّهم يتذكّرون ويتّعظون بمواعظه وأوامره ونواهيه «فإنما يسرناه بلسانك لعلهم يتذكرون»؛ ففي هذا بيانُ أنّ الله يسّر القرآنَ وسهّله بلغةِ العربِ ليتذكّروا ويتّعظوا؛ فأنزله بلسانٍ عربيٍّ مبينٍ سهلٍ واضح؛ ولقد يسّرنا القرآنَ للذكرِ فهل من مدّكر؛ إنا جعلناه قرآنًا عربيًّا لعلّكم تعقلون؛ فاعلم أنّ الله يسّر القرآنَ لتتذكّر به وتتّعظ وتعمل؛ فما يسّره إلا ليُتدبَّر ويُعمَل به، لا ليُهجَر؛ أفلا يتدبّرون القرآنَ أم على قلوبٍ أقفالها؛ فتدبّر القرآنَ الميسَّر، واتّعظ بمواعظه، واعمل بأوامره؛ فالقرآنُ ميسَّرٌ للذكرى والاتّعاظِ والعمل؛ فأقبل عليه متذكّرًا متّعظًا عاملًا؛ فمن تذكّر بالقرآنِ وعمل به اهتدى، ومن أعرض عنه وهجره ضلّ؛ فاجعل من القرآنِ الميسَّرِ ذكرى تتّعظ بها وتعمل؛ فبتدبّرِ القرآنِ والاتّعاظِ به والعملِ بمقتضاه تُنال الهداية."}},{"n":59,"reflection":{"text":"«فارتقب إنهم مرتقبون»: فانتظر يا محمدُ ما يحلُّ بهم، إنهم منتظرون ما يحلُّ بك؛ ففي هذا تسليةُ النبيِّ ووعيدُ المكذّبين؛ فاصبر وانتظر نصرَ الله ووعده، فالعاقبةُ للمتّقين، فاثبت على الحقِّ وانتظر فرجَ الله، فوعدُ الله آتٍ لا محالة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الصبرُ وانتظارُ نصرِ الله ووعده، والثباتُ على الحق."},"action":{"text":"تأمّل تسليةَ النبيِّ ووعيدَ المكذّبين: فارتقب، يا محمدُ، وانتظر ما وعدك الله من النصرِ والظفر، وما يحلُّ بالمكذّبين من العذابِ والهلاك؛ إنهم مرتقبون منتظرون ما يحلُّ بك من دوائرِ السوءِ بزعمهم، فسيعلمون لمن تكون العاقبة «فارتقب إنهم مرتقبون»؛ ففي هذا تسليةٌ للنبيِّ ﷺ وأمرٌ له بالصبرِ والانتظار، ووعيدٌ للمكذّبين؛ فأمر الله نبيَّه أن يرتقب وعدَ الله بالنصرِ وعذابِ أعدائه؛ فالعاقبةُ للنبيِّ والمؤمنين، والهلاكُ للمكذّبين؛ فاصبر أنت وانتظر نصرَ الله ووعده وفرجه؛ واعلم أنّ العاقبةَ للمتّقين؛ والعاقبةُ للتقوى؛ إنّ العاقبةَ للمتّقين؛ فاثبت على الحقِّ ولو كثر المكذّبون؛ وانتظر فرجَ الله ونصره؛ فوعدُ الله آتٍ لا محالة؛ فانتظروا إنا معكم منتظرون؛ فمن صبر على الحقِّ وانتظر نصرَ الله ظفر، ومن جزع وترك الحقَّ خاب؛ فاجعل صبرك على الحقِّ وانتظارك لنصرِ الله عبادةً؛ فبالصبرِ والثباتِ والانتظارِ تُنال العاقبةُ الحسنةُ والنصرُ من الله؛ فاصبر إنّ وعدَ الله حقّ."}}]}],"coverage":{"covered":59,"total":59}};
